        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    subprocess = __import__("subprocess")
    os = __import__("os")
    concurrent = __import__("concurrent.futures")

    if not varargs:
        # Run command without additional arguments
        try:
            result = subprocess.run(cmd, capture_output=True, **kwargs)
            return result.returncode, result.stdout + result.stderr
        except Exception as exc:
            return 1, str(exc).encode()

    # Split varargs into partitions respecting _max_length
    partitions: list[list[str]] = []
    current: list[str] = []
    current_len = 0
    for arg in varargs:
        # Estimate length including a space separator
        arg_len = len(arg) + 1
        if current_len + arg_len > _max_length and current:
            partitions.append(current)
            current = []
            current_len = 0
        current.append(arg)
        current_len += arg_len
    if current:
        partitions.append(current)

    # Ensure concurrency is at least 1
    max_workers = max(1, target_concurrency)
    # Use ThreadPoolExecutor for concurrent execution
    with concurrent.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = []

        def _run(cmd_args: list[str]) -> subprocess.CompletedProcess:
            try:
                return subprocess.run(cmd_args, capture_output=True, **kwargs)
            except Exception as exc:
                # Return a dummy CompletedProcess with error output
                return subprocess.CompletedProcess(
                    args=cmd_args, returncode=1, stdout=b"", stderr=str(exc).encode()
                )

        for part in partitions:
            full_cmd = list(cmd) + part
            futures.append(executor.submit(_run, full_cmd))

        overall_returncode = 0
        combined_output = b""
        for future in futures:
            result = future.result()
            combined_output += result.stdout + result.stderr

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    # Validate input
    try:
        if seq is None:
            raise TypeError("seq cannot be None")
        # Minimal check: sequence-like
        if not hasattr(seq, "__len__") or not hasattr(seq, "__getitem__"):
            raise TypeError("seq must be a sequence")
        # Ensure all elements are strings
        for elem in seq:
            if not isinstance(elem, str):
                raise TypeError("All elements of seq must be strings")
        arr = list(seq)
        n = len(arr)
        if n < 2:
            return arr
        # Deterministic seed based on contents
        seed = 0
        for elem in arr:
            for ch in elem:
                seed = ((seed * 31) + ord(ch)) & 0xffffffff
        # LCG constants
        a = 1664525
        c = 1013904223
        m = 2**32
        state = seed
        # Fisher-Yates shuffle
        for i in range(n - 1, 0, -1):
            state = (a * state + c) % m
            j = state % (i + 1)
            arr[i], arr[j] = arr[j], arr[i]
        return arr
    except Exception as e:
        raise RuntimeError(f"Error shuffling sequence: {e}") from e

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    import random
    try:
        lst = list(seq)
    except Exception as e:
        raise TypeError("Input must be a sequence of strings") from e
    for item in lst:
        if not isinstance(item, str):
            raise TypeError("All elements must be strings")
    seed = hash(tuple(lst))
    rnd = random.Random(seed)
    rnd.shuffle(lst)
    return lst

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("version input must be a string")
    numbers = []
    current = []
    for ch in s:
        if ch.isdigit():
            current.append(ch)
        else:
            if current:
                try:
                    numbers.append(int("".join(current)))
                except ValueError:
                    # This should not happen as current only contains digits
                    pass
                current = []
    if current:
        try:
            numbers.append(int("".join(current)))
        except ValueError:
            pass
    return tuple(numbers)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    s = s.strip()
    if not s:
        raise ValueError("Version string cannot be empty")
    parts = s.split('.')
    nums = []
    for part in parts:
        if not part:
            continue
        try:
            nums.append(int(part))
        except ValueError:
            raise ValueError(f"Invalid numeric component: '{part}'") from None
    if not nums:
        raise ValueError("No numeric components found")
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """
    Convert a version string into a tuple of integers for comparison.
    Example: "1.2.3" -> (1, 2, 3)
    The function is tolerant to extra characters and missing parts
    and returns an empty tuple when there are no numeric components.
    Raises TypeError if the input is not a string.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected string, got {type(s).__name__}")
    # Find contiguous digit sequences in the string.
    import re
    parts = re.findall(r'\d+', s)
    if not parts:
        return ()
    try:
        return tuple(int(part) for part in parts)
    except ValueError:
        # This should not happen as we matched only digits, but guard anyway.
        raise ValueError(f"Could not parse version components from {s}")

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    import os, sys

    # If not on Windows, return command unchanged
    if not sys.platform.startswith("win"):
        return tuple(cmd)

    if not cmd:
        return cmd

    # Helper to quote a path if it contains spaces, quotes or backslashes
    def _quote(path: str) -> str:
        if any(ch in path for ch in (" ", "\"", "\\")):
            return f'"{path}"'
        return path

    first = cmd[0]
    new_cmd = tuple(cmd)  # default

    # Attempt to handle shebangs in script files
    if isinstance(first, str) and os.path.isfile(first):
        try:
            with open(first, "rb") as f:
                line = f.readline().decode(errors="ignore")
            if line.startswith("#!"):
                # Extract interpreter from shebang line
                interpreter = line[2:].strip().split()[0]
                # Resolve relative path relative to the script location
                script_dir = os.path.dirname(first) or "."
                if not os.path.isabs(interpreter) and interpreter.startswith("."):
                    interpreter = os.path.normpath(os.path.join(script_dir, interpreter))
                interpreter = os.path.normpath(interpreter)
                interpreter = _quote(interpreter)

                # Build a new command tuple: interpreter, script, args...
                new_cmd = (interpreter, first) + tuple(cmd[1:])
        except Exception:
            # Skip shebang handling on any error
            pass

    # Quote remaining items if needed (e.g., spaces, quotes)
    final_cmd = []
    for arg in new_cmd:
        if isinstance(arg, str):
            final_cmd.append(_quote(arg))
        else:
            final_cmd.append(str(arg))
    return tuple(final_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    try:
        import os
        import sys
    except Exception:
        return cmd

    # If not running on Windows, return unchanged
    if os.name != "nt":
        return cmd

    cmd_list = list(cmd)

    if not cmd_list:
        return cmd

    first = cmd_list[0]
    _, ext = os.path.splitext(first)

    # If first element is already an executable or a batch/command script, leave it
    if ext.lower() in {".exe", ".bat", ".cmd", ".ps1", ".com"}:
        return tuple(cmd_list)

    # Try to detect a shebang line if the file exists
    if os.path.isfile(first):
        try:
            with open(first, "rb") as f:
                first_line = f.readline().decode("utf-8", errors="ignore").strip()
            if first_line.startswith("#!"):
                # Replace shebang script with the current Python executable
                return (sys.executable,) + tuple(cmd_list[1:])
        except Exception:
            # If anything goes wrong reading the file, ignore and fall through
            pass

    # If the command looks like a module name (no path and not .py),
    # use -m switch to invoke it via the current interpreter.
    if not os.path.sep in first and not first.endswith(".py"):
        return (sys.executable, "-m", first) + tuple(cmd_list[1:])

    return tuple(cmd_list)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters
    ----------
    cache : mapping or cache interface
        Object used to store cached values. Must support the methods
        ``get`` and ``__setitem__`` or ``set``.
    key : callable, optional
