        def wrapper(*args, **kwargs):
            try:
                cache_key = key(*args, **kwargs)
            except Exception:
                # If key generation fails, fall back to using the args/kwargs
                # tuple directly as key
                cache_key = (args, tuple(sorted(kwargs.items())))

            try:
                if hasattr(cache, "get"):
                    cached_val = cache.get(cache_key, object())
                else:
                    # Expect cache to support mapping interface
                    cached_val = cache[cache_key]
                if cached_val is not object():
                    return cached_val
            except KeyError:
                # Value not in cache
                pass
            except Exception as exc:
                # Any other cache related exceptions are not fatal; just
                # re‑compute the value.
                cached_val = object()

            if lock is not None:
                with lock:
                    try:
                        result = func(*args, **kwargs)
                        cache[cache_key] = result
                        return result
                    except Exception as exc:
                        raise
            else:
                try:
                    result = func(*args, **kwargs)
                    try:
                        cache[cache_key] = result
                    except Exception:
                        # If storing in cache fails, ignore the error
                        pass
                    return result
                except Exception as exc:
                    raise

        # Preserve metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

