    """
    Format an exception into a readable string with limited call stack depth and path level.
    """
    # Helper function to shorten file paths
    def _shrink_path(path, max_parts):
        import os as _os
        parts = path.split(_os.sep)
        if len(parts) > max_parts:
            return _os.sep.join(['...'] + parts[-max_parts:])
