            max_level = 30
        if not isinstance(max_path_level, int) or max_path_level <= 0:
            max_path_level = 5

        # Retrieve traceback from the exception
        tb = getattr(e, "__traceback__", None)
        # If no traceback available, return minimal info
        if tb is None:
            return f'{e.__class__.__name__}: {e}' if e is not None else ''

        # Extract traceback entries
        import traceback as _traceback, os as _os
        extracted_tb = _traceback.extract_tb(tb)
        if not extracted_tb:
            return f'{e.__class__.__name__}: {e}'
        # Limit to max_level frames
        extracted_tb = extracted_tb[:max_level]

        # Build formatted message
        parts = [f'Exception type: {e.__class__.__name__}', f'Exception message: {e}']
        parts.append('Traceback (most recent call last):')
        for frame in extracted_tb:
            filename = _shrink_path(frame.filename, max_path_level)
            parts.append(f'  File "{filename}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                parts.append(f'    {frame.line.strip()}')
        return "\n".join(parts)
    except Exception:
        # Fallback: plain str of exception if formatting fails
        return str(e) if e is not None else ''

