            encoded_bytes = text_buffer.encode(encoding)
            byte_count = len(encoded_bytes)
        except Exception:
            return -1

        mode = 'w' if overwrite else 'a'
        try:
            # Use encoding parameter during write
            with open(file_name, mode, encoding=encoding, errors='strict') as f:
                f.write(text_buffer)
            return byte_count
        except Exception:
            return -1

@staticmethod
