@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to its default state.
    """
    try:
        if not isinstance(cls, type):
            raise TypeError(f"Expected class type for cls, got {type(cls)}")
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        root.setLevel(logging.WARNING)
        logging.basicConfig()
    except Exception as exc:
        try:
            logging.getLogger().error("Error resetting logging: %s", exc)
        except Exception:
            raise

@classmethod
def _reset_logging(cls):
    """
    Reset logging configuration to default,
    removing all existing handlers and setting a basic format.
    """
    try:
        import logging
        root = logging.getLogger()
        for handler in root.handlers[:]:
            root.removeHandler(handler)
        logging.basicConfig(level=logging.INFO,
                            format='%(levelname)s:%(name)s:%(message)s')
    except Exception:
        # Silently ignore any errors related to logging configuration
        pass

def _getTargetClass(self):
    """
    Determine the base implementation name by removing known suffixes
    ('Py' or 'Fallback') from the concrete class name.
    """
    try:
        class_name = str(self.__class__.__name__)
    except Exception as exc:
        # In case __class__ or __name__ is not accessible, fall back to empty string
        class_name = ""
    suffixes = ("Py", "Fallback")
    for suffix in suffixes:
        if class_name.endswith(suffix):
            return class_name[: -len(suffix)]
    return class_name

