def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent."""
    # Ensure we have a list
    try:
        cls_list = list(classes)
    except TypeError:
        raise TypeError("Expected an iterable of classes") from None

    # Validate that all items are classes
    for cls in cls_list:
        if not isinstance(cls, type):
            raise TypeError(f"Item {cls!r} is not a class")

    # Build the minimal set: keep classes that are not superclasses of any other
    minimal = []
    for candidate in cls_list:
        # Determine if this candidate is a superclass of any other class in the list
        is_super = False
        for other in cls_list:
            if other is candidate:
                continue
            try:
                if issubclass(other, candidate):
                    is_super = True
                    break
            except TypeError:
                # Skip if not a class; should not happen due to earlier check
                continue
        if not is_super:
            minimal.append(candidate)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent.

    Given an iterable of class objects, this function returns a new list
    containing only those classes that are not a superclass of any other
    class in the input.  The resulting list preserves the order of the
    first occurrence of each class from the input and removes duplicates.
    """
    # Validate input is iterable
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("minimalBases expects an iterable of classes") from None

    # Convert to list to allow multiple passes
    base_list = list(classes)

    # Verify all elements are class types
    for idx, cls in enumerate(base_list):
        if not isinstance(cls, type):
            raise TypeError(f"element at position {idx} is not a class object: {cls!r}")

    # Find all classes that are supersets of another class in the list
    supersets = set()
    for c in base_list:
        for other in base_list:
            if c is not other:
                try:
                    if issubclass(other, c):
                        supersets.add(c)
                        break
                except TypeError:
                    # Skip if other is not a class (shouldn't happen due to check)
                    pass

    # Build result while preserving order and removing duplicates
    result = []
    seen = set()
    for cls in base_list:
        if cls in supersets:
            # Skip superclass that is redundant
            continue
        if cls in seen:
            # Skip duplicate
            continue
        seen.add(cls)
        result.append(cls)

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    results = {}
    for name in dir(self):
        if name.startswith('_'):
            continue
        try:
            attr = getattr(self, name)
        except Exception:
            continue
        if callable(attr):
            continue
        desc = None
        # Try to get the descriptor from the class (handles @property etc.)
        try:
            cls_attr = getattr(self.__class__, name)
            desc = getattr(cls_attr, "__doc__", None)
        except Exception:
            pass
        # If still not found, try the instance attribute's docstring
        if desc is None:
            try:
                desc = getattr(attr, "__doc__", None)
            except Exception:
                pass
        # Fallback to a custom 'description' attribute
        if desc is None:
            try:
                desc = getattr(attr, "description", None)
            except Exception:
                pass
        if all or desc:
            results[name] = desc
    return results

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
        """
        Return a mapping of attribute names to their associated description strings.
        By default only attributes defined directly on the instance's class are
        returned. If ``all=True`` the result includes inherited attributes as well.
        """
        result = {}
        # Determine the set of names to consider
        if all:
            names = dir(self)
        else:
            # Names defined directly on the class (excluding inherited)
            names = list(self.__class__.__dict__.keys())

        for name in names:
            # Skip private/internal attributes except those that are special.
            if name.startswith("_") and not name.startswith("__"):
                continue
            # Retrieve the attribute (may raise AttributeError if not present)
            try:
                attr = getattr(self, name)
            except AttributeError:
                continue

            desc = ""
            # Try to fetch a docstring from the attribute
            try:
                # If it's a property, get the fget docstring
                if isinstance(attr, property):
                    desc = attr.fget.__doc__ or ""
                # If it's a function/method
                elif callable(attr):
                    desc = attr.__doc__ or ""
                # If it's a class or module
                elif hasattr(attr, "__doc__"):
                    desc = attr.__doc__ or ""
            except Exception:
                desc = ""

            result[name] = desc or ""
        return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        names_set = set()

        # Collect class-level attributes, ignoring callables and private ones
        for key, value in vars(type(self)).items():
            if callable(value):
                continue  # skip methods, descriptors, etc.
            if not all and key.startswith("_"):
                continue
            names_set.add(key)

        # Collect instance-level attributes if they exist
        if hasattr(self, "__dict__"):
            for key in self.__dict__:
                if not all and key.startswith("_"):
                    continue
                names_set.add(key)

        return sorted(names_set)
    except Exception as exc:
        raise RuntimeError(f"Failed to retrieve attribute names: {exc}") from exc

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a bool")
    attrs = set()
    if all:
        classes = self.__class__.__mro__
    else:
        classes = [self.__class__]
    for cls in classes:
        # Regular attributes
        for name, value in vars(cls).items():
            if name.startswith('_'):
                continue
            if callable(value):
                continue
            attrs.add(name)
        # Annotated attributes
        annotations = getattr(cls, "__annotations__", {})
        for name in annotations:
            if name.startswith('_'):
                continue
            attrs.add(name)
    return tuple(sorted(attrs))

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")
    try:
        # Collect attribute names from class and instance dictionaries
        class_attrs = {k for k, v in vars(type(self)).items() if not callable(v)}
        instance_attrs = {k for k, v in vars(self).items() if not callable(v)}
        attr_names = class_attrs | instance_attrs
        # Exclude private names unless `all=True`
        if not all:
            attr_names = {name for name in attr_names if not name.startswith("_")}
        return sorted(attr_names)
    except Exception as e:
        raise RuntimeError(f"Failed to retrieve interface names: {e}") from e

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    # Prepare the target list
    if output is None:
        result = []
    else:
        if isinstance(output, list):
            result = output
        else:
            # If the output provided is not a list, raise a type error
            raise TypeError(f"output must be a list (got {type(output).__name__})")

    # Helper function to recursively flatten allowed containers
    def _flatten(item):
        # If item is None, skip it
        if item is None:
            return

        # Strings and bytes should be treated as atomic elements
        if isinstance(item, (str, bytes)):
            result.append(item)
            return

        # Try to detect if item is an iterable container
        try:
            iterator = iter(item)
        except TypeError:
            # Not iterable, treat as atomic
            result.append(item)
            return

        # Determine if we should expand this container
        # Skip expanding if it's a single interface or implements spec.
        # Since we don't know those types, we conservatively expand only tuples,
        # lists, and sets. Other iterables (like generators, dicts, etc.) are
        # expanded as their elements as they are usually meant for iteration.
        if isinstance(item, (tuple, list, set)):
            for sub in item:
                _flatten(sub)
        else:
            # For other iterables (e.g., dicts, generators), iterate through
            # their elements. For dictionaries, we expand over keys.
            for sub in iterator:
                _flatten(sub)

    # Normalize the initial sequence
    if isinstance(sequence, (str, bytes)):
        # Treat a single string/bytes as a single argument
        result.append(sequence)
    else:
        try:
            for elem in sequence:
                _flatten(elem)
        except TypeError:
            # sequence is not iterable, treat it as a single argument
            result.append(sequence)

    return result

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Delegations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Helper to flatten a single element
    def _process_elem(elem):
        if isinstance(elem, (list, tuple)):
            # If the tuple/list has exactly two elements, treat it as a pair
            # (interface, implements).  Otherwise recursively flatten its contents.
            if len(elem) == 2:
                output.append(elem)
            else:
                for sub in elem:
                    _process_elem(sub)
        else:
            # It's not a sequence – treat it as an individual interface or
            # declaration spec and add it directly.
            output.append(elem)

    try:
        # If the provided sequence is not iterable (e.g., a single object),
        # process it as a single element.
        try:
            iterator = iter(sequence)
        except TypeError:
            _process_elem(sequence)
            return output

        for item in iterator:
            _process_elem(item)
    except Exception:
        # On unexpected errors simply return the current output without
        # raising further.
        pass

    return output

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    try:
        if sequence is None:
            return output
        for item in sequence:
            # Expand only tuples, lists, or sets, but not strings or bytes
            if isinstance(item, (list, tuple, set)) and not isinstance(item, (str, bytes)):
                # Recursively normalize nested sequences
                _normalizeargs(item, output)
            else:
                # Append the item as is
                output.append(item)
    except Exception:
        # In case of any unexpected error, simply return what has been collected so far
        return output
    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.
    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import sys
        import os
    except Exception:
        # If imports fail, we cannot reliably determine environment, default to False
        return False
    # Check for PyPy
    if hasattr(sys, "pypy_version_info"):
        return False
    # Check PURE_PYTHON environment variable
    try:
        pure_python_env = os.getenv("PURE_PYTHON")
    except Exception:
        pure_python_env = None
    if pure_python_env:
        pure_python_env = pure_python_env.strip().lower()
        if pure_python_env in {"1", "true", "t", "yes", "y", "on"}:
            return False
    return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        # Attempt to obtain the required optimizations
        required = _c_optimizations_required()
    except NameError:
        # The required function is not defined; cannot determine the opposite
        return None
    except Exception:
        # Any other error retrieving required optimizations
        return None
    try:
        # Return the logical opposite of the required optimizations
        # This works for booleans; if required is a collection, we treat failure as None
        return not required
    except Exception:
        # If required is not a type that can be inverted directly, safely return None
        return None

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        # Interpret this as optimizations not being required (i.e., ignored)
        return False
    except Exception:
        # If an unexpected error occurs, default to ignoring optimizations
        return False

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    Returns a boolean indicating whether optimizations are ignored.
    """
    try:
        # Assume `_c_optimizations_required` exists and returns a truthy/falsy value
        return not _c_optimizations_required()
    except Exception:
        # If `_c_optimizations_required` cannot be called (e.g., not defined or errors),
        # default to `True` to indicate that optimizations are ignored.
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required
        return True

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations aren't required
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True, we are running a pure-Python build
        # and therefore do NOT require C optimizations.
        return not bool(PURE_PYTHON)
    except NameError:
        # PURE_PYTHON not defined – assume optimizations are not required
        return False
    except Exception:
        # Unexpected error – be conservative and do not request C optimizations
        return False

