            raise ValueError(
                "Histogram reinitialization failed: no 'initial_value' nor callable 'make_bins' available."
            )
    except Exception as exc:
        raise RuntimeError("Failed to reinitialize histogram bins during reset.") from exc
    return

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    lines = []
    # Determine iterable of points
    try:
        # Prefer attribute `points` if it exists
        points = getattr(self, "points", None)
        if points is None:
            points = self  # assume the instance itself is iterable
    except Exception:
        # Fallback: empty iterable
        points = []
    for item in points:
        try:
            coord, value = item
        except Exception:
            # Skip items that cannot be unpacked into (coord, value)
            continue
        # Format coordinate
        if isinstance(coord, (list, tuple)):
            try:
                coord_str = separator.join(map(str, coord))
            except Exception:
                coord_str = str(coord)
        else:
            coord_str = str(coord)
        # Format value
        if isinstance(value, (str, bytes)):
            val_str = str(value)
        elif isinstance(value, (list, tuple)):
            try:
                val_str = separator.join(map(str, value))
            except Exception:
                val_str = str(value)
        elif hasattr(value, "__iter__") and not isinstance(value, (str, bytes)):
            try:
                val_str = separator.join(map(str, value))
            except Exception:
                val_str = str(value)
        elif value is None:
            val_str = ""
        else:
            val_str = str(value)
        lines.append(coord_str + separator + val_str)
    # Assemble final CSV string
    result_lines = []
    if header is not None:
        result_lines.append(str(header).rstrip("\n"))
    result_lines.extend(lines)
    return "\n".join(result_lines)

def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    try:
        for point in self:
            # Try to extract coordinates and value if the point has attributes
            if hasattr(point, "coordinate") or hasattr(point, "coords"):
                coord_obj = getattr(point, "coordinate", getattr(point, "coords", None))
                val_obj = getattr(point, "value", None)
                # If coordinates are not provided, fall back to the point itself
                if coord_obj is None:
                    coord_obj = point
            else:
                coord_obj = point
                val_obj = None

            # Convert coordinates to a list of string parts
            if isinstance(coord_obj, (list, tuple)):
                coord_parts = [str(c) for c in coord_obj]
            else:
                coord_parts = [str(coord_obj)]

            # Convert value to a list of string parts
            if val_obj is None:
                value_parts = []
            elif isinstance(val_obj, (list, tuple)):
                value_parts = [str(v) for v in val_obj]
            else:
                value_parts = [str(val_obj)]

            line = separator.join(coord_parts + value_parts)
            lines.append(line)
    except Exception as exc:
        raise RuntimeError(f"Error converting graph to CSV: {exc}") from exc

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
        """Get error indices corresponding to a coordinate."""
        # validate input type
        if not isinstance(coord_name, str):
            raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

        # Attempt to retrieve the error indices dictionary
        try:
            err_dict = getattr(self, "_err_indices", {})
        except AttributeError:
            # If the attribute is missing, treat as empty
            err_dict = {}

        # Ensure the dictionary is a mapping
        if not isinstance(err_dict, dict):
            raise ValueError(f"_err_indices attribute is expected to be a dict, got {type(err_dict).__name__}")

        # Return a copy of the indices list for the requested coordinate, or an empty list otherwise
        indices = err_dict.get(coord_name, [])
        if not isinstance(indices, (list, tuple)):
            raise ValueError(f"Error indices for {coord_name!r} should be a list or tuple, got {type(indices).__name__}")

        return list(indices)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError(f'invalid numeric input: {exc}') from exc
    if bins_arr.ndim != 1 or edges_arr.ndim != 1:
        raise ValueError('bins and edges must be 1-dimensional')
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError('edges length must be one greater than bins length')
    widths = np.diff(edges_arr)
    if np.any(widths < 0):
        raise ValueError('edges must be non-decreasing')
    return float(np.sum(bins_arr * widths))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert inputs to lists to allow for indexing
    try:
        bins_list = list(bins)
        edges_list = list(edges)
    except TypeError as exc:
        raise TypeError("`bins` and `edges` must be iterable") from exc

    # Basic checks on the edge list
    if len(edges_list) == 0:
        raise ValueError("`edges` must contain at least one element")
    if len(edges_list) == 1:
        # Width zero, integral is zero
        return 0.0

    # The number of bins must be one less than the number of edges
    if len(bins_list) != len(edges_list) - 1:
        raise ValueError(
            f"Number of bins ({len(bins_list)}) must be one less than number of "
            f"edges ({len(edges_list)})"
        )

    total = 0.0
    for i, val in enumerate(bins_list):
        try:
            # Bin width
            width = edges_list[i + 1] - edges_list[i]
        except Exception as exc:
            raise ValueError(f"Failed to compute width for bin index {i}") from exc

        try:
            # Convert both value and width to float and accumulate
            total += float(val) * float(width)
        except Exception as exc:
            raise ValueError(f"Invalid bin value at index {i}") from exc

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to list to allow repeated iteration
    try:
        bins = list(bins)
    except Exception as exc:
        raise TypeError("`bins` must be an iterable of numbers") from exc
    try:
        edges = list(edges)
    except Exception as exc:
        raise TypeError("`edges` must be an iterable of numbers") from exc

    n_bins = len(bins)

    if len(edges) != n_bins + 1:
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one more than number of bins ({n_bins})"
        )

    # Verify monotonically increasing edges
    for i in range(n_bins):
        try:
            left = float(edges[i])
            right = float(edges[i + 1])
        except Exception as exc:
            raise TypeError("`edges` must contain numeric values") from exc
        if right < left:
            raise ValueError(
                f"Edge at position {i+1} ({right}) is smaller than preceding edge {left}"
            )

    # Compute integral
    total = 0.0
    for i in range(n_bins):
        try:
            bin_value = float(bins[i])
        except Exception as exc:
            raise TypeError(f"Bin at position {i} ({bins[i]}) is not numeric") from exc
        width = edges[i + 1] - edges[i]
        total += bin_value * width

    return total

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Helper functions to detect message types when the concrete classes
    # (e.g., FillRequest, Source) may not be importable in this scope.
    def _is_fill_request(msg):
        """Return True if *msg* looks like a FillRequest."""
        try:
            # Most FIX message objects expose a `MsgType` attribute
            # (e.g., "F" for a FillRequest).  In the absence of that,
            # we fall back to a name check.
            msg_type = getattr(msg, "MsgType", None)
            if msg_type in ("F", "FR", "FillRequest"):
                return True
            return getattr(msg.__class__, "__name__", "") in ("FillRequest",)
        except Exception:
            return False

    def _is_source(msg):
        """Return True if *msg* looks like a Source instance."""
        try:
            return getattr(msg.__class__, "__name__", "") in ("Source", "SourceSeq")
        except Exception:
            return False

    # If the entire object is a source sequence, we reject it outright.
    if _is_source(seq):
        return False

    # If *seq* is a single message, check it directly.
    if not hasattr(seq, "__iter__") or isinstance(seq, (bytes, str)):
        return _is_fill_request(seq)

    # Otherwise treat *seq* as an iterable collection of messages.
    try:
        for item in seq:
            if _is_source(item):
                # If any element is a source, the whole sequence is invalid.
                return False
            if _is_fill_request(item):
                return True
    except Exception:
        # If we cannot iterate or an unexpected error occurs, return False.
        return False

    # No fill‑request elements found.
    return False

