def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # If seq is None, cannot be a FillRequestSeq
    if seq is None:
        return False

    # Check if seq is a Source sequence; if so, we must return False.
    try:
        # If a class named 'Source' is available, use it for type checking.
        if isinstance(seq, Source):
            return False
    except NameError:
        # If 'Source' is not defined, try an alternative heuristic: check
        # the class name for a word that looks like "Source".
        try:
            if type(seq).__name__.lower().startswith("source"):
                return False
        except Exception:
            pass

    # Check if seq itself is a FillRequest element.
    try:
        if isinstance(seq, FillRequest):
            return True
    except NameError:
        # If 'FillRequest' is not defined, try to identify it by type name.
        try:
            if type(seq).__name__.lower() == "fillrequest":
                return True
        except Exception:
            pass

    # If seq is iterable, check each element for being a FillRequest.
    try:
        for item in seq:
            try:
                if isinstance(item, FillRequest):
                    return True
            except NameError:
                # Fallback: check type name of the item.
                try:
                    if type(item).__name__.lower() == "fillrequest":
                        return True
                except Exception:
                    continue
        # If we reached here, no FillRequest found in seq.
        return False
    except TypeError:
        # seq is not iterable; we already checked the type above.
        return False

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

