def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate input
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both 'd1' and 'd2' must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("'level' must be an integer")

    def _diff(sub_d1, sub_d2, lvl):
        """
        Recursive helper to compute the difference between two dictionaries
        up to a specified recursion depth.
        """
        # If recursion depth limit reached, do not examine deeper
        if lvl == 0:
            return {}

        result = {}
        for key, val1 in sub_d1.items():
            if key not in sub_d2:
                # Key missing in sub_d2 → include it
                result[key] = val1
            else:
                val2 = sub_d2[key]
                # If both values are dictionaries, recurse
                if isinstance(val1, dict) and isinstance(val2, dict):
                    new_lvl = lvl - 1 if lvl > 0 else lvl  # preserve -1 for infinite
                    diff_sub = _diff(val1, val2, new_lvl)
                    if diff_sub:
                        result[key] = diff_sub
                else:
                    # Include if values differ
                    if val1 != val2:
                        result[key] = val1
        return result

    try:
        return _diff(d1, d2, level)
    except RecursionError as exc:
        # In case of pathological cyclic structures we keep behaviour sane
        raise ValueError("Maximum recursion depth exceeded while computing difference") from exc

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")

    # Helper for recursion limit
    def _diff(inner_d1, inner_d2, depth):
        result = {}
        for key, val1 in inner_d1.items():
            if key not in inner_d2:
                # Key missing in d2 – include as is
                result[key] = val1
                continue

            val2 = inner_d2[key]
            # If both values are dicts and recursion is allowed
            if isinstance(val1, dict) and isinstance(val2, dict):
                # Determine next depth; -1 denotes infinite recursion
                next_depth = depth - 1 if depth > 0 else -1
                sub = _diff(val1, val2, next_depth)
                if sub:
                    result[key] = sub
            else:
                # Non-dict values: include if they differ
                if val1 != val2:
                    result[key] = val1
        return result

    # Resolve initial depth: -1 means infinite
    initial_depth = level
    if initial_depth == 0:
        # No recursion – just compare top-level values
        return _diff(d1, d2, 0)
    else:
        return _diff(d1, d2, initial_depth)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("both arguments must be dictionaries")
    if level is not None and not isinstance(level, int):
        raise TypeError("level must be an integer or None")

    def _diff(a, b, lvl):
        result = {}
        for key, val in a.items():
            if key not in b:
                # Value not present in second dictionary
                result[key] = val
                continue
            val2 = b[key]
            # If both are dicts and recursion is allowed
            if isinstance(val, dict) and isinstance(val2, dict):
                if lvl == 0:
                    # Cannot recurse further, treat as differing values
                    result[key] = val
                else:
                    next_lvl = lvl - 1 if lvl > 0 else -1
                    sub_diff = _diff(val, val2, next_lvl)
                    if sub_diff:
                        result[key] = sub_diff
            else:
                # For non-dict values, include if they differ
                if val != val2:
                    result[key] = val
        return result

    return _diff(d1, d2, level)

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")

    # Normalize level: -1 indicates unlimited recursion
    unlimited = level == -1
    # Use a copy of the result
    result = {}

    for key, val1 in d1.items():
        if key not in d2:
            # Key absent in d2: include value from d1
            result[key] = val1
            continue

        val2 = d2[key]
        # Compare values
        if isinstance(val1, dict) and isinstance(val2, dict):
            # Both values are dictionaries, potentially recurse
            if unlimited or level > 0:
                sub_level = -1 if unlimited else level - 1
                sub_diff = difference(val1, val2, sub_level)
                if sub_diff:
                    result[key] = sub_diff
            else:
                # Recursion not allowed: treat as a difference if the dicts differ
                if val1 != val2:
                    result[key] = val1
        else:
            # Values are not both dictionaries
            if val1 != val2:
                result[key] = val1

    return result

