def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expression for a valid label key or value (simplified).
    # A label key can optionally include a namespace prefix before a slash.
    key_regex = re.compile(r"^(?:[A-Za-z0-9](?:[A-Za-z0-9._-]{0,61}[A-Za-z0-9])?/)?[A-Za-z0-9][A-Za-z0-9._-]{0,61}[A-Za-z0-9]$")
    value_regex = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]{0,61}[A-Za-z0-9]$|^$")

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            # Convert bytes to string for regex matching
            key_str = key.decode() if isinstance(key, bytes) else key
            if not key_regex.match(key_str):
                errors.append(
                    {key_str: f"Label key '{key_str}' does not match the regex [{key_regex.pattern}]"}
                )

        # Validate value
        if isinstance(value, (list, tuple, set)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    errors.append({repr(elem): "expected string or bytes-like object"})
                else:
                    elem_str = elem.decode() if isinstance(elem, bytes) else elem
                    if not value_regex.match(elem_str):
                        errors.append(
                            {repr(elem): f"Label value '{elem_str}' does not match the regex [{value_regex.pattern}]"}
                        )
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({repr(value): "expected string or bytes-like object"})
            else:
                value_str = value.decode() if isinstance(value, bytes) else value
                if not value_regex.match(value_str):
                    errors.append(
                        {value_str: f"Label value '{value_str}' does not match the regex [{value_regex.pattern}]"}
                    )

    if errors:
        raise ValidationError(errors)

