    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.  When ``first_level`` is ``True`` all
    identifying fields (``name``, ``apiVersion``, ``kind`` and ``namespace``)
    are copied from the original manifest unchanged.

    Raises:
        TypeError: if ``manifest_dict`` is not a dictionary
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    result = {}
    # fields that should be preserved when building the top‑level schema
    identifying_fields = {"name", "apiVersion", "kind", "namespace"}

    for key, value in manifest_dict.items():
        try:
            if isinstance(value, dict):
