    return result

def generate_default_observer_schema_list(manifest_list, first_level=False):
    """
    Recursive helper to generate a default observer_schema structure from a list of items.

    Args:
        manifest_list (list): A list of Kubernetes resource dictionaries or simple items.
        first_level (bool, optional): If True, indicates that the list represents
            the whole observer schema of a Kubernetes resource.

    Returns:
        list: Generated partial observer_schema list.
