    if not isinstance(manifest_list, list):
        raise ValueError("manifest_list must be a list")

    result = []
    try:
        for item in manifest_list:
            if isinstance(item, dict):
                result.append(generate_default_observer_schema_dict(item, first_level=False))
            elif isinstance(item, list):
                result.append(generate_default_observer_schema_list(item, first_level=False))
            else:
