        # The most common places are `observer_schema`, `observer.schemas`, or
        # `spec.observers` (a dict mapping kinds to schemas).
        # We'll try to discover the attribute automatically.
        observer_schema_map = None
        if hasattr(spec, "observer_schema"):
            observer_schema_map = getattr(spec, "observer_schema")
        elif hasattr(spec, "observer") and hasattr(spec.observer, "schemas"):
            observer_schema_map = getattr(spec.observer, "schemas")
        elif hasattr(spec, "observers") and isinstance(getattr(spec, "observers"), dict):
            observer_schema_map = getattr(spec, "observers")

        # If none of the expected attributes exist, create a new empty dict
        if observer_schema_map is None:
            observer_schema_map = {}
            # Attach it back to the spec so the caller can see the new dict
            if hasattr(spec, "observer_schema"):
                setattr(spec, "observer_schema", observer_schema_map)
            elif hasattr(spec, "observer"):
                setattr(spec.observer, "schemas", observer_schema_map)
            else:
                setattr(spec, "observers", observer_schema_map)

