        if manifest is None:
            return {}
    except Exception:
        # In case of unexpected attribute errors, return an empty mapping
        return {}

    default_schemas = {}

    # Manifest can be a list or a dict
    if isinstance(manifest, dict):
        items = manifest.items()
    elif isinstance(manifest, list):
        items = [(None, r) for r in manifest]
    else:
        # Unsupported type; return empty mapping
        return {}

    for name, resource in items:
        if resource is None:
