                resource.get("apiVersion") if isinstance(resource, dict) else None
            )
            meta_name = None
            if hasattr(resource, "metadata"):
                meta_name = getattr(resource.metadata, "name", None) or (
                    getattr(resource.metadata, "name") if hasattr(resource.metadata, "name") else None
                )
            elif isinstance(resource, dict):
                meta_name = resource.get("metadata", {}).get("name")

            resource_name = name or meta_name
            if not resource_name:
