def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    errors = []

    # Optional extraction of spec version from the 'type' field
    if extract_spec_version:
        type_val = inventory.get("type")
        if not isinstance(type_val, str):
            errors.append("Missing or non‑string 'type' field for spec version extraction")
        else:
            # Try to find a 'vX' suffix after a dash
            try:
                import re
                m = re.search(r"-(v\d+)$", type_val)
                if m:
                    # Store only the digits as the spec_version
                    self.spec_version = m.group(1)[1:]
                else:
                    errors.append(f"Could not extract spec version from type '{type_val}'")
            except Exception as exc:
                errors.append(f"Regex error while extracting spec version: {exc}")

    # Basic required keys and type checks
    required_keys = {"name": str, "type": str, "data": dict}
    for key, expected_type in required_keys.items():
        if key not in inventory:
            errors.append(f"Missing required key: '{key}'")
        else:
            if not isinstance(inventory[key], expected_type):
                errors.append(f"Key '{key}' must be of type {expected_type.__name__}")

    if errors:
        raise ValueError("Inventory validation failed: " + "; ".join(errors))

    return True

