def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check that every required digest listed in the manifest is present in the
    collection of used digests, and that no digests are used that are not
    required. Raises ValueError with details when the check fails, otherwise
    returns True.
    """
    # Validate input types
    if not isinstance(manifest_files, (list, tuple)):
        raise TypeError("manifest_files must be a list or tuple")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be a set, list, or tuple")

    # Normalise digests_used to a set of strings
    try:
        digests_used = {str(d) for d in digests_used}
    except Exception as exc:
        raise ValueError(f"Error processing digests_used: {exc}") from exc

    required_digests = set()
    for entry in manifest_files:
        try:
            if isinstance(entry, dict):
                digest = entry.get('digest')
            else:
                # Assume entry itself is the digest value
                digest = entry
            if digest is None:
                # No digest information; skip or log as needed
                continue
            required_digests.add(str(digest))
        except Exception as exc:
            # Entry could not be processed; likely malformed
            raise ValueError(f"Malformed manifest entry {entry}: {exc}") from exc

    # Determine missing and unused digests
    missing_in_use = required_digests - digests_used
    unused_in_use = digests_used - required_digests

    error_messages = []
    if missing_in_use:
        error_messages.append(
            f"Use missing required digests: {', '.join(sorted(missing_in_use))}"
        )
    if unused_in_use:
        error_messages.append(
            f"Digests used but not required: {', '.join(sorted(unused_in_use))}"
        )

    if error_messages:
        raise ValueError("; ".join(error_messages))

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used.

        Raises:
            TypeError: If inputs are of unexpected types.
            ValueError: If digests used are missing from the manifest or
                        digests in the manifest are unused.
        """
        try:
            if manifest_files is None or digests_used is None:
                raise TypeError("Both manifest_files and digests_used must be provided")

            # Extract digests from the manifest
            digests_in_manifest = set()
            for entry in manifest_files:
                if isinstance(entry, dict):
                    # Individual digest
                    if "digest" in entry:
                        dig = entry["digest"]
                        if not isinstance(dig, (str, bytes)):
                            continue
                        digests_in_manifest.add(dig)
                    # Multiple digests under a list
                    if "digests" in entry:
                        for dig in entry["digests"]:
                            if isinstance(dig, (str, bytes)):
                                digests_in_manifest.add(dig)
                elif isinstance(entry, (str, bytes)):
                    digests_in_manifest.add(entry)
                else:
                    # Unsupported entry type – skip silently
                    pass

            digests_used_set = set(digests_used)

            # Digests used but not present in the manifest
            missing_in_manifest = digests_used_set - digests_in_manifest
            if missing_in_manifest:
                raise ValueError(
                    f"Digests used but not present in manifest: "
                    f"{sorted(missing_in_manifest)}"
                )

            # Digests present in manifest but not used
            unused_in_manifest = digests_in_manifest - digests_used_set
            if unused_in_manifest:
                raise ValueError(
                    f"Digests present in manifest but not used: "
                    f"{sorted(unused_in_manifest)}"
                )

            # All checks passed
            return True

        except Exception as exc:
            # Re-raise known exceptions unchanged
            if isinstance(exc, (TypeError, ValueError)):
                raise
            # Wrap unexpected exceptions
            raise RuntimeError("Error checking digests presence and usage") from exc

def check_digests_present_and_used(self, manifest_files, digests_used):
