def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    try:
        # Ensure prior is an InventoryValidator (basic duck typing)
        if not hasattr(prior, 'inventory'):
            raise ValueError('prior object lacks an inventory attribute')
        if not hasattr(self, 'inventory'):
            raise ValueError('self object lacks an inventory attribute')

        current_inv = self.inventory
        prior_inv = prior.inventory

        # Compare version numbers if they exist
        current_version = getattr(current_inv, 'version', None)
        prior_version = getattr(prior_inv, 'version', None)
        if current_version is None or prior_version is None:
            raise ValueError('Inventories missing version information')

        if current_version <= prior_version:
            raise ValueError('Current inventory version must be greater than prior version')

        # Ensure every item/key in the prior inventory appears in the current inventory
        if hasattr(prior_inv, 'keys'):
            # Assume prior_inv behaves like a dict
            for key in prior_inv.keys():
                if key not in current_inv:
                    raise ValueError(f'Key "{key}" from prior inventory not found in current inventory')
                # Optional: check that types are consistent
                if type(prior_inv[key]) != type(current_inv[key]):
                    raise ValueError(f'Type mismatch for key "{key}": prior {type(prior_inv[key])}, current {type(current_inv[key])}')
        else:
            # If prior_inv is not dict-like, attempt iterable comparison
            try:
                for item in prior_inv:
                    if item not in current_inv:
                        raise ValueError(f'Item "{item}" from prior inventory not found in current inventory')
            except TypeError:
                # Fallback: just compare hashable collections if possible
                pass

        return True
    except Exception as exc:
        raise ValueError(f'Invalid prior version: {exc}')

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    try:
        # Ensure the prior argument is an instance of the same class
        if not isinstance(prior, type(self)):
            raise TypeError("prior must be an instance of the same type as self")

        # Prevent self-referential check
        if prior is self:
            raise ValueError("prior cannot be the same object as self")

        # Basic version comparison if a 'version' attribute is provided
        if hasattr(self, 'version') and hasattr(prior, 'version'):
            if not isinstance(self.version, (int, float, str)) or not isinstance(prior.version, (int, float, str)):
                raise TypeError("version attributes must be int, float, or str")
            if self.version >= prior.version:
                raise ValueError("self.version must be less than prior.version for a valid prior")

        # If an explicit method exists to check prior relationship, use it
        if hasattr(self, 'is_prior_of') and callable(self.is_prior_of):
            if not self.is_prior_of(prior):
                raise ValueError("prior object is not a valid prior version according to is_prior_of()")

        # If we reach here, all basic checks passed
        return True

    except Exception as exc:
        # Re-raise with a clear message, preserving the original exception type
        raise type(exc)(f"validate_as_prior_version failed: {exc}") from exc

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Ensure we can work with the input
    if inventory is None:
        return {}
    if not isinstance(version, (str, int)):
        raise ValueError(f"Invalid version type: {type(version)}")

    result = {}

    # Helper to add a mapping
    def _add_mapping(logical_path, files):
        try:
            if logical_path is None:
                return
            files_set = set(files) if files is not None else set()
            if logical_path in result:
                result[logical_path].update(files_set)
            else:
                result[logical_path] = files_set
        except Exception:
            # Silently ignore invalid entries
            pass

    # Case 1: inventory is already the desired map
    if isinstance(inventory, dict):
        # Check if the dict keys look like logical paths (string) and values are iterable
        if all(isinstance(v, (set, list, tuple, frozenset)) for v in inventory.values()):
            return {k: set(v) for k, v in inventory.items()}

    # Case 2: inventory is a mapping from logical paths to metadata
    if isinstance(inventory, dict):
        for key, value in inventory.items():
            # If key looks like a logical path and value contains files
            if isinstance(key, str) and isinstance(value, dict):
                try:
                    v = value.get('version')
                    if v == version or (isinstance(v, list) and version in v):
                        # Prefer 'content_files' then 'files'
                        files = value.get('content_files') or value.get('files')
                        _add_mapping(key, files)
                except Exception:
                    continue
            # If key looks like logical path and value is a list/iterable
            elif isinstance(key, str) and isinstance(value, (list, set, tuple)):
                _add_mapping(key, value)
        return result

    # Case 3: inventory is a list/iterable of dicts
    try:
        iter(inventory)
    except TypeError:
        # Not iterable, return empty
        return result

    for item in inventory:
        if not isinstance(item, dict):
            continue
        try:
            v = item.get('version')
            if v == version or (isinstance(v, list) and version in v):
                logical_path = item.get('logical_path')
                files = item.get('content_files') or item.get('files')
                _add_mapping(logical_path, files)
        except Exception:
            continue

    return result

def get_logical_path_map(inventory, version):
    """
    Build a mapping from logical paths to sets of content file paths for a
    specific version within the given inventory.

    Parameters
    ----------
    inventory : Mapping or Sequence
        Represents all available state versions. The representation can be:
            * a dictionary mapping ``version`` -> state object/dict
            * a sequence (list, tuple, generator, etc.) of state objects/dicts.
            Each state is expected to expose either a ``files`` attribute/key
            (an iterable of objects/records) or a ``logical_path_map`` attribute/`key`
            that directly provides the desired mapping.

    version : hashable
        The exact key identifying the desired state in the inventory.

    Returns
    -------
    dict
        Mapping from ``logical_path_in_state`` (str or hashable value) to a set of
        ``content_file`` paths (each is a str).

    Raises
    ------
    TypeError
        If ``inventory`` is not a mapping or a sequence.
    ValueError
        If the requested ``version`` cannot be found in the inventory.
    """
    # Helper to extract the state for the requested version
    state = None
    if isinstance(inventory, dict):
        state = inventory.get(version)
    elif hasattr(inventory, "__iter__"):
        for cand in inventory:
            # Objects may expose ``version`` attribute or key
            if hasattr(cand, "version"):
                if cand.version == version:
                    state = cand
                    break
            elif isinstance(cand, dict) and cand.get("version") == version:
                state = cand
                break
    else:
        raise TypeError("inventory must be a mapping or a sequence of state objects")

    if state is None:
        raise ValueError(f"Version {version!r} not found in inventory")

    # Determine the structure that contains file information
    files_iterable = None
    if isinstance(state, dict):
        # Prefer a direct mapping if available
        if "logical_path_map" in state:
            # Already the desired mapping; just copy values to sets
            logical_map = {}
            for lp, content in state["logical_path_map"].items():
                if isinstance(content, (list, set)):
                    logical_map[lp] = set(content)
                else:
                    logical_map[lp] = {content}
            return logical_map
        if "files" in state:
            files_iterable = state["files"]
        else:
            raise ValueError("state dict lacks 'files' or 'logical_path_map' keys")
    else:
        # Assume object has attributes
        if hasattr(state, "logical_path_map"):
            logical_map = {}
            for lp, content in getattr(state, "logical_path_map").items():
                if isinstance(content, (list, set)):
                    logical_map[lp] = set(content)
                else:
                    logical_map[lp] = {content}
            return logical_map
        if hasattr(state, "files"):
            files_iterable = getattr(state, "files")
        else:
            raise ValueError("state object lacks 'files' or 'logical_path_map' attributes")

    # Build the mapping
    result = {}
    for entry in files_iterable:
        # ``entry`` may be a dict or an object with attributes
        if isinstance(entry, dict):
            logical_path = entry.get("logical_path") or entry.get("path")
            content_file = entry.get("content_file") or entry.get("file")
        else:
            logical_path = getattr(entry, "logical_path", None) or getattr(entry, "path", None)
            content_file = getattr(entry, "content_file", None) or getattr(entry, "file", None)

        if logical_path is None or content_file is None:
            continue  # Skip entries that don't contain the required fields

        # Store the content file in a set
        if logical_path in result:
            result[logical_path].add(content_file)
        else:
            result[logical_path] = {content_file}

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")
    if not isinstance(version, str):
        raise TypeError(f"version must be a str, got {type(version).__name__}")

    # Helper to determine if v1 is a later or equal version compared to v2
    def _is_later_or_equal(v1, v2):
        try:
            return float(v1) >= float(v2)
        except (ValueError, TypeError):
            return v1 >= v2  # fallback to string comparison

    if version not in inventory:
        raise KeyError(f"Version '{version}' not found in inventory")

    result_map = {}

    # Initialize maps for the target version
    target_data = inventory.get(version, {})
    target_paths = target_data.get("paths", {})
    if not isinstance(target_paths, dict):
        raise ValueError(f"Expected 'paths' dict in inventory for version '{version}'")

    for logical_path, content_files in target_paths.items():
        if not isinstance(logical_path, str):
            raise TypeError(f"Logical path keys must be strings, got {type(logical_path).__name__}")
        # Normalize content_files to a set
        if isinstance(content_files, (set, list, tuple)):
            files_set = set(content_files)
        else:
            files_set = {content_files}
        result_map[logical_path] = files_set

    # Extend maps with later versions
    for v, data in inventory.items():
        if not isinstance(v, str):
            continue  # skip non-string keys
        if _is_later_or_equal(v, version):
            paths = data.get("paths", {})
            if not isinstance(paths, dict):
                continue
            for logical_path, content_files in paths.items():
                if not isinstance(logical_path, str):
                    continue
                files_set = result_map.setdefault(logical_path, set())
                if isinstance(content_files, (set, list, tuple)):
                    files_set.update(content_files)
                else:
                    files_set.add(content_files)

    return result_map

