def validate_fixity(self, fixity, manifest_files):
    """
    Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Allow an empty or missing fixity block
    if not fixity:
        return

    # Validate that manifest_files is provided and is iterable
    if manifest_files is None or not hasattr(manifest_files, "__iter__"):
        raise ValueError("manifest_files must be an iterable of file names")

    manifest_set = set(manifest_files)

    # The fixity block should be a list/tuple of dictionaries
    if not isinstance(fixity, (list, tuple)):
        raise ValueError(f"Fixity block must be a list or tuple, got {type(fixity).__name__}")

    required_keys = {"file", "checksum", "type"}

    for idx, entry in enumerate(fixity):
        # Each entry must be a dict
        if not isinstance(entry, dict):
            raise ValueError(
                f"Fixity entry at index {idx} must be a dict, got {type(entry).__name__}"
            )

        # Check for required keys
        missing_keys = required_keys - entry.keys()
        if missing_keys:
            raise ValueError(
                f"Fixity entry at index {idx} is missing keys: {sorted(missing_keys)}"
            )

        # Validate file path
        file_path = entry["file"]
        if not isinstance(file_path, str) or not file_path:
            raise ValueError(
                f"Fixity entry at index {idx} has an invalid 'file' value: {file_path}"
            )
        if file_path not in manifest_set:
            raise ValueError(
                f"Fixity entry at index {idx} references '{file_path}' which is not present in the manifest"
            )

        # Validate checksum
        checksum = entry["checksum"]
        if not isinstance(checksum, str) or not checksum:
            raise ValueError(
                f"Fixity entry at index {idx} has an invalid 'checksum' value: {checksum}"
            )

        # Validate type
        checksum_type = entry["type"]
        if not isinstance(checksum_type, str) or not checksum_type:
            raise ValueError(
                f"Fixity entry at index {idx} has an invalid 'type' value: {checksum_type}"
            )

    # If all checks pass, silently return
    return None
