def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Validate input
    if not isinstance(folder, str):
        raise TypeError(f"folder must be a string, got {type(folder).__name__}")
    if not os.path.isdir(folder):
        raise ValueError(f"Provided path '{folder}' is not a directory or does not exist")

    data = {}
    try:
        for entry in os.listdir(folder):
            path = os.path.join(folder, entry)
            if not os.path.isfile(path):
                continue
            base, ext = os.path.splitext(entry)
            ext = ext.lower().lstrip('.')
            if not base:
                continue  # skip files without a name part
            # Initialize group dict if not present
            group = data.setdefault(base, {})
            # Handle duplicates: store as list if multiple files of same extension
            if ext in group:
                existing = group[ext]
                if isinstance(existing, list):
                    existing.append(path)
                else:
                    group[ext] = [existing, path]
            else:
                group[ext] = path
    except OSError as e:
        raise RuntimeError(f"Failed to explore folder '{folder}': {e}") from e

    return data

