def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
        Mapping from XML basename to a sub-dictionary of file paths and their raw data.
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Identify all base names that have an XML entry
            xml_bases = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base, ext = os.path.splitext(os.path.basename(info.filename))
                if ext.lower() == ".xml":
                    xml_bases.add(base)

            # If we found no XML files, return an empty dict
            if not xml_bases:
                return {}

            # Group files by the identified XML base names
            packages = {}
            for info in zf.infolist():
                if info.is_dir():
                    continue
                cur_base, _ = os.path.splitext(os.path.basename(info.filename))
                if cur_base in xml_bases:
                    try:
                        data = zf.read(info)
                    except Exception:
                        data = None
                    packages.setdefault(cur_base, {})[info.filename] = data

            return packages

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Zip file not found: {zip_path}") from e
    except zipfile.BadZipFile as e:
        raise ValueError(f"Bad or corrupted zip file: {zip_path}") from e
    except PermissionError as e:
        raise PermissionError(f"Permission denied when accessing zip file: {zip_path}") from e
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred while reading the zip file '{zip_path}': {e}") from e

