def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re
    try:
        if issue is None:
            return (None, None)

        # Obtém o texto contido no elemento, caso seja um objeto com atributo .text
        text = issue.text if hasattr(issue, 'text') else str(issue)
        if not text:
            return (None, None)

        text = text.strip()

        # Padrão para extração do número ou intervalo de números no início da string
        number_match = re.match(r'^\s*(\d+)(?:-(\d+))?', text)
        number = None
        if number_match:
            if number_match.group(2):
                number = f'{number_match.group(1)}-{number_match.group(2)}'
            else:
                number = number_match.group(1)

        # Padrões para identificação de suplementação (Suppl, Spe, etc.)
        sup_pattern = r'(suppl|spe|s\.?uppl|supp|suppl\.?|spe\.?)\s*\.?\s*(\d+)?'
        sup_match = re.search(sup_pattern, text, re.I)

        supplement = None
        if sup_match:
            if sup_match.group(2):
                try:
                    supplement = int(sup_match.group(2))
                except (TypeError, ValueError):
                    supplement = None
            else:
                # Indica presença de suplemento sem número
                supplement = None

        return (number, supplement)

    except Exception:
        # Em caso de qualquer erro inesperado, devolve valores nulos
        return (None, None)

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    raw = None
    try:
        if hasattr(issue, "text") and issue.text is not None:
            raw = issue.text.strip()
        else:
            raw = str(issue).strip()
    except Exception:
        return (None, None)

    if not raw:
        return (None, None)

    # Remove surrounding tags if any
    raw = re.sub(r'^<[^>]+>|</[^>]+>$', '', raw).strip()

    # Find first number or number-range
    num_match = re.search(r'(\d+(?:-\d+)?)', raw)
    number = None
    if num_match:
        number = num_match.group(1)
    else:
        # maybe number is after 's' prefix like "s2" -> extract digits
        alt_num_match = re.search(r's(\d+)', raw, re.IGNORECASE)
        if alt_num_match:
            number = alt_num_match.group(1)

    # Extract supplement part
    supplement = None
    try:
        # Remove the number substring from text
        if num_match:
            supp_part = raw.replace(num_match.group(0), '', 1)
        elif alt_num_match:
            supp_part = raw.replace(alt_num_match.group(0), '', 1)
        else:
            supp_part = raw

        # Clean up
        supp_part = supp_part.strip()
        # Remove trailing punctuation
        supp_part = re.sub(r'[.,\s]+$', '', supp_part)
        # Remove leading tags or markers
        supp_part = re.sub(r'^[<\s]+|[>\s]+$', '', supp_part)

        if supp_part:
            supplement = supp_part
    except Exception:
        supplement = None

    # Convert numeric string to int if possible
    if number is not None:
        if '-' not in number:
            try:
                number = int(number)
            except Exception:
                pass

    return (number, supplement)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Ensure indent is a non‑negative integer
    try:
        indent = int(indent)
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0

    # Recursive helper that builds the formatted string
    def _format(obj, level):
        try:
            spacing = ' ' * (level * indent)

            # If debugging, show the object's type
            if debug:
                type_line = f"{spacing}{type(obj).__name__}"
            else:
                type_line = None

            # Handle dictionaries
            if isinstance(obj, dict):
                if not obj:
                    body = f"{spacing}{{}}"
                else:
                    lines = [f"{spacing}{{"]
                    for k, v in obj.items():
                        val_str = _format(v, level + 2).lstrip()
                        lines.append(f"{spacing}  {repr(k)}: {val_str}")
                    lines.append(f"{spacing}}}")
                    body = "\n".join(lines)
                return ("\n".join([type_line, body]) if debug else body)

            # Handle lists, tuples, sets
            if isinstance(obj, (list, tuple, set)):
                open_sym = type(obj).__name__ + "("
                close_sym = ")"
                if not obj:
                    body = f"{spacing}{open_sym}{close_sym}"
                else:
                    lines = [f"{spacing}{open_sym}"]
                    for item in obj:
                        val_str = _format(item, level + 2).lstrip()
                        lines.append(f"{spacing}  {val_str}")
                    lines.append(f"{spacing}{close_sym}")
                    body = "\n".join(lines)
                return ("\n".join([type_line, body]) if debug else body)

            # Handle custom objects with __dict__
            if hasattr(obj, "__dict__") and obj is not self:
                if not vars(obj):
                    body = f"{spacing}{{}}"
                else:
                    lines = [f"{spacing}{{"]
                    for attr, val in vars(obj).items():
                        val_str = _format(val, level + 2).lstrip()
                        lines.append(f"{spacing}  {attr}: {val_str}")
                    lines.append(f"{spacing}}}")
                    body = "\n".join(lines)
                return ("\n".join([type_line, body]) if debug else body)

            # Fallback to string representation
            return f"{spacing}{repr(obj)}"

        except RecursionError:
            return f"{spacing}<RecursionError>"
        except Exception as exc:
            return f"{spacing}<Error: {exc}>"

    # Generate representation for the current instance
    return _format(self, 0).rstrip()

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent argument
    if not isinstance(indent, int):
        raise TypeError("indent must be an integer")
    if indent < 0:
        raise ValueError("indent must be non-negative")

    # Helper function for recursive pretty printing
    def _pretty(obj, level, seen):
        prefix = ' ' * (level * 4)

        # Detect circular references
        obj_id = id(obj)
        if obj_id in seen:
            return f"{prefix}<recursion>"
        seen.add(obj_id)

        # Pretty-print dictionaries
        if isinstance(obj, dict):
            if not obj:
                return f"{prefix}{{}}"
            lines = [f"{prefix}{"}
            for k in sorted(obj, key=lambda x: str(x)):
                v = obj[k]
                lines.append(' ' * ((level + 1) * 4) + f"{repr(k)}: {_pretty(v, level + 1, seen)}")
            lines.append(f"{prefix}}}")
            return "\n".join(lines)

        # Pretty-print lists, tuples, sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                type_name = type(obj).__name__
                return f"{prefix}{type_name}()"
            open_char = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
            close_char = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
            lines = [f"{prefix}{open_char}"]
            for item in obj:
                lines.append(' ' * ((level + 1) * 4) + _pretty(item, level + 1, seen))
            lines.append(f"{prefix}{close_char}")
            return "\n".join(lines)

        # Pretty-print objects that expose a __dict__
        if hasattr(obj, "__dict__"):
            try:
                attrs = getattr(obj, "__dict__")
                if not attrs:
                    return f"{prefix}{obj.__class__.__name__}()"
                lines = [f"{prefix}{obj.__class__.__name__}("]
                for k in sorted(attrs):
                    v = attrs[k]
                    lines.append(' ' * ((level + 1) * 4) + f"{k}={_pretty(v, level + 1, seen)}")
                lines.append(f"{prefix})")
                return "\n".join(lines)
            except Exception:
                return f"{prefix}{repr(obj)}"

        # Fallback: use repr
        return f"{prefix}{repr(obj)}"

    result = _pretty(self, indent, set())

    if debug:
        header = f"<{self.__class__.__name__} id={hex(id(self))}>\n"
        result = header + result

    return result

