def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        if not isinstance(indent, int) or indent < 0:
            raise ValueError("indent must be a non-negative integer")
        spaces = ' ' * indent
        lines = []
        header = f"{self.__class__.__name__}"
        if debug:
            header += f" (id=0x{id(self):x})"
        header += ":"
        lines.append(spaces + header)
        for key, value in sorted(self.__dict__.items()):
            line_prefix = spaces + ' ' * 4
            try:
                if hasattr(value, 'pretty') and callable(value.pretty):
                    val_str = value.pretty(indent + 4, debug)
                    lines.append(f"{line_prefix}{key}:\n{val_str}")
                elif isinstance(value, (list, tuple)):
                    sub_lines = []
                    for idx, item in enumerate(value):
                        try:
                            if hasattr(item, 'pretty') and callable(item.pretty):
                                sub = item.pretty(indent + 8, debug)
                                sub_lines.append(f"{' ' * (indent + 8)}- Item {idx}:\n{sub}")
                            else:
                                sub_lines.append(f"{' ' * (indent + 8)}- {repr(item)}")
                        except Exception:
                            sub_lines.append(f"{' ' * (indent + 8)}- {repr(item)}")
                    lines.append(f"{line_prefix}{key}:")
                    if sub_lines:
                        lines.extend(sub_lines)
                    else:
                        lines.append(f"{line_prefix}  []")
                elif isinstance(value, dict):
                    sub_lines = []
                    for k, v in value.items():
                        try:
                            if hasattr(v, 'pretty') and callable(v.pretty):
                                sub = v.pretty(indent + 8, debug)
                                sub_lines.append(f"{' ' * (indent + 8)}- {repr(k)}:\n{sub}")
                            else:
                                sub_lines.append(f"{' ' * (indent + 8)}- {repr(k)}: {repr(v)}")
                        except Exception:
                            sub_lines.append(f"{' ' * (indent + 8)}- {repr(k)}: {repr(v)}")
                    lines.append(f"{line_prefix}{key}:")
                    if sub_lines:
                        lines.extend(sub_lines)
                    else:
                        lines.append(f"{line_prefix}  {{}}")
                else:
                    lines.append(f"{line_prefix}{key}: {repr(value)}")
            except Exception:
                lines.append(f"{line_prefix}{key}: [error]")
        return '\n'.join(lines)
    except Exception as exc:
        return f"<Error in pretty: {exc}>"

