    to unicode strings. This wrapper ensures that, when used under Python 2, a
    unicode return value is encoded to a bytestring (UTF-8) before being returned.
    Under Python 3, the original function is returned unchanged.
    """
    # Determine Python major version without importing sys
    try:
        py_major = sys.version_info[0]
    except NameError:
        # If sys is not available or not imported, assume Python 2
        py_major = 2

    if py_major >= 3:
        # No conversion needed in Python 3
        return namefunc

    # We're in Python 2, create a wrapper that encodes unicode results
    def wrapper(*args, **kwargs):
        result = namefunc(*args, **kwargs)
        # In Python 2, unicode is the string type; bytestrings are 'str'
        if isinstance(result, unicode):
            try:
                return result.encode('utf-8')
            except Exception:
                # Fallback: convert to string in a best-effort way
                return str(result)
        return result

    return wrapper

