            major = int(pieces["major"])
            minor = int(pieces["minor"])
        except KeyError as e:
            raise ValueError(f"Missing required key for semver: {e.args[0]}")
        patch = int(pieces.get("patch", 0))
        version = f"{major}.{minor}.{patch}"
        if "pre" in pieces:
            pre = str(pieces["pre"])
            if pre:
                version += f"-{pre}"
        if "build" in pieces:
            build = str(pieces["build"])
            if build:
                version += f"+{build}"
        return version

    if style == "date":
        # Expected keys: year, month, day, hour (optional), minute (optional)
        if not isinstance(pieces, dict):
            raise ValueError("date style requires pieces to be a mapping with keys")
        try:
            year = int(pieces["year"])
            month = int(pieces["month"])
            day = int(pieces["day"])
        except KeyError as e:
            raise ValueError(f"Missing required key for date: {e.args[0]}")
        date_part = f"{year:04d}-{month:02d}-{day:02d}"
        hour = pieces.get("hour")
        minute = pieces.get("minute")
        if hour is not None or minute is not None:
            hour = int(hour) if hour is not None else 0
            minute = int(minute) if minute is not None else 0
            time_part = f"{hour:02d}:{minute:02d}"
            return f"{date_part} {time_part}"
        return date_part

    # Default/simple style: join the pieces with '.' using string conversion.
    if pieces_iter is None:
        # pieces was a dict; use values without guaranteed order
        pieces_iter = pieces.values()
    result_parts = [str(part) for part in pieces_iter if part is not None and str(part) != ""]
    return ".".join(result_parts) if result_parts else ""

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic validation
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if len(pieces) > 5:
        raise ValueError("pieces can contain at most 5 elements (major, minor, patch, prerelease, build)")

    # Pad pieces to 5 elements with None to simplify indexing
    padded = list(pieces) + [None] * (5 - len(pieces))

    major, minor, patch, prerelease, build = padded

    # Convert numeric parts to string if they are numbers
    def fmt_part(part):
        if part is None:
            return None
        return str(part)

    major_s = fmt_part(major)
    minor_s = fmt_part(minor)
    patch_s = fmt_part(patch)
    prerelease_s = fmt_part(prerelease)
    build_s = fmt_part(build)

    # Define formatting for supported styles
    if style == "semver":
        # Semantic Versioning: MAJOR.MINOR.PATCH-PRERELEASE+BUILD
        version = ""
        if major_s is None:
            raise ValueError("major version required for semver")
        version += major_s
        if minor_s is not None:
            version += "." + minor_s
        else:
            version += ".0"
        if patch_s is not None:
            version += "." + patch_s
        else:
            version += ".0"
        if prerelease_s:
            version += "-" + prerelease_s
        if build_s:
            version += "+" + build_s
        return version

    elif style == "plain":
        # Just numeric components separated by dots
        if major_s is None:
            raise ValueError("major version required for plain")
        components = [major_s]
        components.append(minor_s if minor_s is not None else "0")
        components.append(patch_s if patch_s is not None else "0")
        return ".".join(components)

    elif style == "pep440":
        # Python packaging version: MAJOR.MINOR.PATCH[.PRERELEASE][+BUILD]
        # PRERELEASE format uses optional 'rc' or 'a/b' etc; we just prepend 'rc' if numeric
        if major_s is None:
            raise ValueError("major version required for pep440")
        version = major_s
        if minor_s is not None:
            version += "." + minor_s
        else:
            version += ".0"
        if patch_s is not None:
            version += "." + patch_s
        else:
            version += ".0"
        if prerelease_s:
            # Simplistic: if prerelease numeric, prefix 'rc', else keep as is
            if prerelease_s.isdigit():
                version += "rc" + prerelease_s
            else:
                version += prerelease_s
        if build_s:
            version += "+" + build_s
        return version

    elif style == "do_not_use":
        # A style that explicitly advises against usage
        raise NotImplementedError("The 'do_not_use' style is not supported.")

    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: semver, plain, pep440.")

