    try:
        if style == 'plain':
            # Simple concatenation
            return '.'.join(_token_to_str(p) for p in parts)

        elif style == 'semantic':
            # Expect major, minor, patch, optional prerelease, optional build
            if not isinstance(parts, list) or len(parts) < 3:
                raise ValueError("Semantic style requires at least three components")
