                    prerelease = '.'.join(str(_token_to_str(t)) for t in parts[3])
                else:
                    prerelease = _token_to_str(parts[3])
            if len(parts) > 4:
                build = _token_to_str(parts[4])
            result = base
            if prerelease is not None and prerelease != '':
                result += '-' + prerelease
            if build is not None and build != '':
                result += '+' + build
            return result

        elif style == 'short':
            # Only major.minor.patch
            if len(parts) < 3:
                raise ValueError("Short style requires at least three components")
            return '.'.join(str(_token_to_str(parts[i])) for i in range(3))

        else:
            raise ValueError(f"Unsupported style '{style}'")
    except Exception as exc:
        # Wrap all errors to ensure consistent exception types
        raise RuntimeError(f"Error rendering version: {exc}") from exc

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Basic input validation
    if not isinstance(pieces, (list, tuple)):
        raise TypeError(f"pieces must be a list or tuple, got {type(pieces).__name__}")
    if style is None:
        style = "canonical"
    if not isinstance(style, str):
        raise TypeError(f"style must be a string, got {type(style).__name__}")

    # Helper to extract name/value from each piece
    def _extract(piece):
        if isinstance(piece, dict):
            if "name" not in piece or "value" not in piece:
                raise ValueError("piece dict must contain 'name' and 'value' keys")
            return piece["name"], piece["value"]
        elif isinstance(piece, (list, tuple)) and len(piece) == 2:
            return str(piece[0]), piece[1]
        else:
            raise ValueError(f"each piece must be a dict with 'name'/'value' or a tuple/list of two elements, got {piece!r}")

    names = []
    values = []
    for p in pieces:
        name, value = _extract(p)
        names.append(name)
        values.append(str(value))

    if style == "canonical":
        return ".".join(values)
    elif style == "verbose":
        return ", ".join(f"{n}={v}" for n, v in zip(names, values))
    elif style == "full":
        # In this simple implementation, 'full' behaves like canonical
        return ".".join(values)
    else:
        raise ValueError(f"unknown style '{style}'. Supported styles: canonical, verbose, full")

def plus_or_dot(pieces):
    """Return a '+' if we don't already have one, else return a '.'."""
    try:
        # Use any to efficiently check for presence of '+'
        if any(p == '+' for p in pieces):
