def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import shlex
    # Build command list
    if isinstance(commands, (list, tuple)):
        cmd = list(commands)
    elif isinstance(commands, str):
        cmd = shlex.split(commands)
    else:
        raise ValueError("commands must be a string or an iterable of strings")
    if not cmd:
        raise ValueError("no command specified")
    # Append arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd.extend(args)
        elif isinstance(args, str):
            cmd.extend(shlex.split(args))
        else:
            raise ValueError("args must be a string or an iterable of strings")
    # Verbose output
    if verbose:
        print("Running command:", ' '.join(shlex.quote(arg) for arg in cmd))
    # Run the command
    try:
        stderr_target = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True
        )
        stdout = result.stdout
        stderr = result.stderr if not hide_stderr else None
        return result.returncode, stdout, stderr
    except Exception as exc:
        # Return error code and the exception message
        return -1, "", str(exc)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    # Ensure args is a list
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a list or tuple, got {type(args).__name__}")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands] + list(args)
    elif isinstance(commands, list) or isinstance(commands, tuple):
        cmd = list(commands) + list(args)
    else:
        raise TypeError(f"commands must be a str or a list/tuple, got {type(commands).__name__}")

    # Prepare environment
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError(f"env must be a dict, got {type(env).__name__}")
        env_vars = os.environ.copy()
        env_vars.update(env)
    else:
        env_vars = None  # subprocess will use os.environ

    # Configure stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    if verbose:
        try:
            quoted_cmd = ' '.join(shlex.quote(part) for part in cmd)
        except Exception:
            quoted_cmd = str(cmd)
        print(f"[run_command] Executing: {quoted_cmd}")

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_vars,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=False
        )
        if verbose:
            print(f"[run_command] Return code: {result.returncode}")
            if result.stdout:
                print(f"[run_command] stdout:\n{result.stdout.rstrip()}")
            if not hide_stderr and result.stderr:
                print(f"[run_command] stderr:\n{result.stderr.rstrip()}")
        return result
    except FileNotFoundError as e:
        if verbose:
            print(f"[run_command] Command not found: {e}")
        raise
    except Exception as e:
        if verbose:
            print(f"[run_command] Error executing command: {e}")
        raise

def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    # Global registry for VCS handlers
    global _VCS_HANDLERS
    try:
        _VCS_HANDLERS  # check existence
    except NameError:
        _VCS_HANDLERS = {}
    # Helper function to actually register a callable
    def _register(callable_obj):
        if not isinstance(vcs, str):
            raise ValueError(f"VCS name must be a string, got {type(vcs).__name__}")
        if not callable(callable_obj):
            raise TypeError(f"Provided object '{callable_obj}' is not callable")
        _VCS_HANDLERS[vcs] = callable_obj
        return callable_obj
    # If 'method' is callable, we are directly registering
    if callable(method):
        return _register(method)
    # Otherwise, treat this as a decorator factory
    def decorator(func):
        return _register(func)
    return decorator

def register_vcs_handler(vcs, method=None):
    """
    Create decorator to mark a method as the handler of a VCS.
    If called with both arguments (vcs and method) the method is registered immediately.
    If called with only vcs, a decorator is returned that will register the decorated
    function under the given VCS name.

    The mapping of VCS names to handlers is stored in the function attribute
    `register_vcs_handler.handlers`.  Duplicate registrations raise a ValueError.
    """
    # Ensure the registry exists
    if not hasattr(register_vcs_handler, "handlers"):
        register_vcs_handler.handlers = {}

    # Validate the VCS key
    if not isinstance(vcs, str):
        raise TypeError(f"VCS name must be a string, got {type(vcs).__name__}")

    # Internal helper to perform the actual registration
    def _register(fn):
        if not callable(fn):
            raise TypeError(f"Handler must be callable, got {type(fn).__name__}")
        if vcs in register_vcs_handler.handlers:
            raise ValueError(f"Handler for VCS '{vcs}' is already registered")
        register_vcs_handler.handlers[vcs] = fn
        return fn

    # If a method is supplied directly, register it immediately
    if method is not None:
        return _register(method)

    # Otherwise return a decorator that will register the function when applied
    def decorator(fn):
        return _register(fn)

    return decorator

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        (num_objects, good_objects)

        num_objects   - number of objects (files) checked
        good_objects  - number of objects that passed all active validity checks
    """
    import os
    import hashlib

    # Determine the root directory - allow for multiple naming conventions
    root_dir = getattr(self, "root_path", None) or getattr(self, "root", None) or getattr(self, "base_path", None) or "."
    if not os.path.isdir(root_dir):
        raise ValueError(f"Root path '{root_dir}' is not a directory or does not exist")

    num_objects = 0
    good_objects = 0

    for dirpath, _, filenames in os.walk(root_dir):
        for fname in filenames:
            # Skip digest files themselves
            if fname.endswith(".sha256"):
                continue

            file_path = os.path.join(dirpath, fname)
            num_objects += 1
            valid = True

            if validate_objects:
                try:
                    with open(file_path, "rb") as f:
                        # Simply read to force any I/O errors
                        f.read()
                except Exception as exc:
                    valid = False
                    if show_warnings:
                        print(f"Warning: cannot validate file '{file_path}': {exc}")

            if check_digests:
                digest_path = file_path + ".sha256"
                if os.path.isfile(digest_path):
                    try:
                        with open(digest_path, "r") as df:
                            expected_digest = df.read().strip().lower()
                        # Compute actual digest
                        h = hashlib.sha256()
                        with open(file_path, "rb") as f:
                            for chunk in iter(lambda: f.read(8192), b""):
                                h.update(chunk)
                        actual_digest = h.hexdigest().lower()
                        if actual_digest != expected_digest:
                            valid = False
                            if show_warnings:
                                print(f"Warning: digest mismatch for '{file_path}'. "
                                      f"Expected {expected_digest}, got {actual_digest}")
                    except Exception as exc:
                        valid = False
                        if show_warnings:
                            print(f"Warning: error reading digest for '{file_path}': {exc}")

            if valid:
                good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """
