def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    v = version.strip()
    if not v.isdigit():
        raise ValueError("version must be a numeric string")
    try:
        new_val = int(v) + 1
    except Exception as exc:
        raise ValueError("could not compute next version") from exc
    if v and v[0] == '0':
        # Preserve original width of leading zeros
        width = len(v)
        return str(new_val).zfill(width)
    return str(new_val)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version is None:
        raise ValueError("version cannot be None")
    # Convert to string if it's not
    try:
        ver_str = str(version).strip()
    except Exception as e:
        raise ValueError(f"invalid version input: {e}")
    if not ver_str:
        raise ValueError("empty version string")
    parts = ver_str.split('.')
    if not parts:
        raise ValueError("invalid version format")
    # Ensure all parts are numeric
    for part in parts:
        if not part.isdigit():
            raise ValueError(f"non-numeric version part: '{part}'")
    # Increment the last part
    last = parts[-1]
    try:
        last_val = int(last)
    except Exception as e:
        raise ValueError(f"cannot parse last part as int: {e}")
    incremented = last_val + 1
    # Preserve zero padding if present
    if len(str(incremented)) <= len(last):
        new_last = str(incremented).zfill(len(last))
    else:
        new_last = str(incremented)
    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """
    Return the next version identifier following the existing pattern.
    Handles both zero-prefixed and non-zero-prefixed numeric components.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    try:
        parts = version.split('.')
        # Search for the last numeric component from the right
        for idx in range(len(parts) - 1, -1, -1):
            part = parts[idx]
            if part.isdigit():
                orig_len = len(part)
                try:
                    value = int(part)
                except ValueError:
                    continue
                new_value = value + 1
                new_part = str(new_value).zfill(orig_len) if len(str(new_value)) <= orig_len else str(new_value)
                parts[idx] = new_part
                return '.'.join(parts)
        # If no purely numeric component is found, return the original string
        return version
    except Exception:
        # In case of unexpected errors, return the original version
        return version

def validate_version_inventories(self, version_dirs):
    """
    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure the base attributes exist
    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise AttributeError("Instance must have a 'root_inventory' dictionary attribute.")
    if not hasattr(self, '_differing_digests'):
        self._differing_digests = {}

    import os
    import json

    for idx, vdir in enumerate(version_dirs, start=1):
        try:
            inv_path = os.path.join(vdir, 'inventory.json')
        except Exception as exc:
            raise ValueError(f"Failed to construct inventory path for version dir '{vdir}': {exc}")

        if not os.path.isfile(inv_path):
            raise FileNotFoundError(
                f"Inventory file not found for version '{vdir}' at expected path: {inv_path}"
            )

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv_data = json.load(f)
        except Exception as exc:
            raise RuntimeError(
                f"Failed to read or parse inventory for version '{vdir}': {exc}"
            )

        if not isinstance(inv_data, dict):
            raise ValueError(
                f"Inventory file for version '{vdir}' must contain a JSON object "
                f"mapping file paths to digests; got {type(inv_data).__name__}"
            )

        # Check for duplicate keys - a dict can't have duplicates but validate values are strings
        for path, digest in inv_data.items():
            if not isinstance(digest, str):
                raise ValueError(
                    f"Digest for file '{path}' in inventory of version '{vdir}' must be a string."
                )

        # Validate that the inventory covers all prior files (cumulative check)
        # Build a cumulative view of all files up to this version
        if idx == 1:
            cumulative_inventory = {}
        else:
            cumulative_inventory = dict(self._cumulative_inventories[-1])  # shallow copy
        cumulative_inventory.update(inv_data)

        # Store cumulative for next iteration
        if not hasattr(self, '_cumulative_inventories'):
            self._cumulative_inventories = []
        self._cumulative_inventories.append(cumulative_inventory)

        # Record mismatched digests relative to the root inventory
        for path, inv_digest in inv_data.items():
            root_digest = self.root_inventory.get(path)
            if root_digest is None:
                # New file added after root catalog; no comparison needed
                continue
            if inv_digest != root_digest:
                key = path
                self._differing_digests.setdefault(key, []).append(
                    {'version': idx, 'inventory_digest': inv_digest, 'root_digest': root_digest}
                )

    # The method modifies instance state; return nothing
    return None

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root (contains ``0=repo.namaste``)
        'object' - looks like an OCFL Object (contains a ``0=`` Namaste file but not ``repo``)
        'file'   - a file (any file that is not a Namaste file or a directory)
        other string explains an error description
    """
    import os, re

    try:
        if not os.path.exists(path):
            return f"error: path does not exist"
        if os.path.isfile(path):
            return 'file'

        if os.path.isdir(path):
            # List files directly inside the directory (not recursive)
            entries = os.listdir(path)
            namaste_files = [e for e in entries if e.startswith('0=') and e.endswith('.namaste')]
            if not namaste_files:
                # No Namaste file found – could still be a file but not a directory
                return f"error: no Namaste file found in directory {path}"
            # Check for repo namaste
            for nf in namaste_files:
                if re.search(r'repo\.namaste$', nf):
                    return 'root'
            # Otherwise assume it's an object
            return 'object'

        return f"error: path type not recognized"
    except Exception as exc:
        return f"error: {exc}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if not os.path.exists(path):
            return f"path does not exist: {path}"
    except Exception as exc:
        return f"cannot access path: {exc}"

    # Treat symlinks as their target type
    try:
        if os.path.islink(path):
            # Resolve the link and continue logic on the real target
            path = os.path.realpath(path)
            if not os.path.exists(path):
                return f"link target does not exist: {path}"
    except Exception as exc:
        return f"cannot resolve symlink: {exc}"

    try:
        if os.path.isfile(path):
            return "file"

        if os.path.isdir(path):
            try:
                entries = set(os.listdir(path))
            except Exception as exc:
                return f"cannot list directory contents: {exc}"

            # Check for OCFL storage root indicators
            if "config.yml" in entries and "objects" in entries:
                return "root"

            # Check for OCFL object indicator (Namaste file)
            if "0=*" in entries:
                return "object"

            # Directory that doesn't match known patterns
            return "unknown directory"
    except Exception as exc:
        return f"runtime error: {exc}"

    return "unknown type"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path
    try:
        p = Path(path)
        if not p.exists():
            return f"Path does not exist: {path}"
        if p.is_file():
            return "file"

        # directory handling
        namaste_files = [f for f in p.iterdir() if f.is_file() and f.name.startswith("0=")]
        if not namaste_files:
            return f"No Namaste file found in directory: {path}"
        if len(namaste_files) > 1:
            return f"Multiple Namaste files found in directory: {path}"
        # single namaste file
        namaste_file = namaste_files[0]
        try:
            with namaste_file.open('r', encoding='utf-8') as f:
                # read first non-empty line
                for line in f:
                    line_strip = line.strip()
                    if line_strip:
                        break
                else:
                    return f"Namaste file is empty: {namaste_file}"
        except Exception as exc:
            return f"Could not read namaste file '{namaste_file}': {exc}"
        line_lower = line_strip.lower()
        if "root" in line_lower:
            return "root"
        if "object" in line_lower:
            return "object"
        return f"Unrecognised namaste content in file '{namaste_file}': {line_strip}"
    except Exception as exc:
        return f"Error processing path '{path}': {exc}"

def amend_bzparams(self, params, bug_ids):
    """
    Amend a Bugzilla request parameter dictionary with the supplied bug IDs.

    Parameters
    ----------
    params : dict
        Existing Bugzilla parameters to be updated.
    bug_ids : int | str | Iterable[int | str] | None
        One or more bug identifiers to include in the request.

    Returns
    -------
    None
        The function modifies ``params`` in place.

    Notes
    -----
    The bug identifiers are stored under the ``ids`` key as a comma-separated
    string, which is the format expected by most Bugzilla HTTP APIs.
    """
    # Validate that params is a dictionary
    if not isinstance(params, dict):
        raise TypeError(f"params must be a dict, got {type(params).__name__}")

    try:
        # No identifiers to add – nothing to do
        if bug_ids is None:
            return

        # Normalise various input types into a list of clean string IDs
        if isinstance(bug_ids, str):
            ids = [bug_ids.strip()]
        elif isinstance(bug_ids, int):
            ids = [str(bug_ids)]
        elif hasattr(bug_ids, "__iter__") and not isinstance(bug_ids, (bytes, bytearray, memoryview)):
            ids = []
            for bi in bug_ids:
                if bi is None:
                    continue
                if isinstance(bi, (int, str)):
                    ids.append(str(bi).strip())
                else:
                    raise ValueError(f"bug_ids element must be an int or str; got {type(bi).__name__}")
        else:
            raise ValueError(
                f"bug_ids must be None, int, str, or an iterable of int/str; got {type(bug_ids).__name__}"
            )

        if not ids:
            return

        # Build the comma-separated list expected by Bugzilla
        params["ids"] = ",".join(ids)

    except Exception as exc:
        raise RuntimeError(f"Failed to amend Bugzilla params: {exc}") from exc

