    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    try:
        from ruamel.yaml import nodes as yaml_nodes
    except Exception:
        # If ruamel.yaml is not available, the function cannot operate correctly.
        raise RuntimeError("ruamel.yaml is required for deep_merge_nodes")

    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list of (ScalarNode, Node) tuples")

    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        return isinstance(node, yaml_nodes.MappingNode)

    # Recursive merge of two MappingNodes
    def merge_mapping(node_a, node_b):
        if not is_mapping(node_a) or not is_mapping(node_b):
            # Should not happen; fallback to return node_b
            return node_b

        # Build ordered dicts of inner mappings
        merged_pairs = []
        seen_keys = {}
        # Helper to add mapping pairs into merged_pairs in order
        def add_pairs(mapping_node, overwrite=False):
            for inner_key, inner_val in mapping_node.value:
                k = inner_key.value
                if k in seen_keys:
                    # already seen; update value depending on overwrite flag
                    if overwrite:
                        seen_keys[k] = (inner_key, inner_val)
                else:
                    seen_keys[k] = (inner_key, inner_val)
                    merged_pairs.append((inner_key, inner_val))

        # Start with node_a's pairs
        add_pairs(node_a, overwrite=True)
        # Merge node_b's pairs, overriding earlier ones
        add_pairs(node_b, overwrite=True)

        # Build new MappingNode with the tag of node_a (prefer first)
        return yaml_nodes.MappingNode(
            tag=node_a.tag,
            value=merged_pairs
        )

    result_map = {}
    order = []

    for key_node, val_node in nodes:
        if not isinstance(key_node, yaml_nodes.ScalarNode):
            # skip invalid keys
            continue
        key = key_node.value
        if key in result_map:
            # Merge with existing value
            existing_val = result_map[key]
            if is_mapping(existing_val) and is_mapping(val_node):
                merged_val = merge_mapping(existing_val, val_node)
