    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    try:
        from ruamel.yaml.nodes import MappingNode, ScalarNode
    except Exception as exc:
        raise ImportError("ruamel.yaml.nodes must be available") from exc

    # Helper to recursively merge two MappingNode values
    def merge_mapping_nodes(existing_node, new_node):
        if not isinstance(existing_node, MappingNode) or not isinstance(new_node, MappingNode):
            # If either is not a mapping, return the new node
            return new_node

        merged_entries = {}
        order = []

        # Helper to process entries from a mapping node
        def process_entries(mapping, priority=0):
            for k, v in mapping.value:
                key_val = k.value
                # If key already seen, decide based on priority (0: existing, 1: new)
                if key_val in merged_entries:
                    # Merge
                    if isinstance(merged_entries[key_val][1], MappingNode) and isinstance(v, MappingNode):
                        merged_entries[key_val] = (merged_entries[key_val][0],
                                                   merge_mapping_nodes(merged_entries[key_val][1], v))
                    else:
                        if priority == 1:
                            merged_entries[key_val] = (k, v)
                else:
                    merged_entries[key_val] = (k, v)
                    order.append(key_val)

        # Existing first to preserve order, then new
        process_entries(existing_node, priority=0)
        process_entries(new_node, priority=1)

        merged_value = [(merged_entries[k][0], merged_entries[k][1]) for k in order]
        return MappingNode(tag=existing_node.tag, value=merged_value)

    # Main merge logic
    merged_dict = {}
    key_order = []

    for key_node, val_node in nodes:
        if not isinstance(key_node, ScalarNode):
            # Skip or raise error
            continue
        key_val = key_node.value
        if key_val in merged_dict:
            # Merge with existing
            existing_val = merged_dict[key_val]
            merged_val = merge_mapping_nodes(existing_val, val_node)
            merged_dict[key_val] = merged_val
        else:
            merged_dict[key_val] = val_node
            key_order.append(key_val)

    result = []
    # Use the first key_node encountered for each unique key
    seen_keys = {}
    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val not in seen_keys:
            seen_keys[key_val] = key_node
    for key_val in key_order:
        key_node = seen_keys[key_val]
        result.append((key_node, merged_dict[key_val]))

    return result

