def deep_merge_nodes(nodes):
    '''
    Deep merge a list of (ScalarNode, value_node) tuples.
    '''
    if not isinstance(nodes, list):
        raise ValueError('nodes must be a list')
    result = {}
    order = []

    def is_mapping(node):
        return hasattr(node, 'value') and isinstance(node.value, list) and all(
            isinstance(pair, tuple) and len(pair) == 2 for pair in node.value
        )

    def merge_nodes(a, b):
        """
        Merge two YAML nodes of the same key.
        If both are mapping nodes, merge recursively.
        Otherwise, return the second node (last wins).
        """
        if is_mapping(a) and is_mapping(b):
            merged_pairs = []
            seen_keys = set()

            # Helper to merge or append a pair
            def add_pair(k_node, v_node):
                key = k_node.value
                if key in seen_keys:
                    # Find existing pair and merge its value
                    for idx, (existing_k, existing_v) in enumerate(merged_pairs):
                        if existing_k.value == key:
                            merged_pairs[idx] = (existing_k, merge_nodes(existing_v, v_node))
                            break
                else:
                    merged_pairs.append((k_node, v_node))
                    seen_keys.add(key)

            for k_node, v_node in a.value:
                add_pair(k_node, v_node)
            for k_node, v_node in b.value:
                add_pair(k_node, v_node)

            # Construct a new MappingNode (assumes constructor takes tag and value)
            return a.__class__(tag=a.tag, value=merged_pairs)
        else:
            return b

    for pair in nodes:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError('Each element in nodes must be a tuple of (key_node, value_node)')
        key_node, value_node = pair
        if not hasattr(key_node, 'value'):
            raise ValueError('Key node must have a .value attribute')
        key_str = key_node.value
        if key_str in result:
            # Merge values
            result[key_str] = merge_nodes(result[key_str], value_node)
        else:
            result[key_str] = value_node
            order.append(key_str)

    # Build final list preserving original key node order
    final = [(nodes[idx][0], result[key]) for key, idx in zip(order, range(len(order)))]
    return final

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Import here to keep the module free of imports and handle unexpected usage
    import argparse
    try:
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError('parser must be an argparse.ArgumentParser instance')
        flags = []
        for action in parser._actions:
            # action.option_strings holds the flags for optional arguments; ignore if empty
            flags.extend(action.option_strings)
        # Return a space-separated string of distinct flags; empty if none
        return ' '.join(sorted(set(flags)))
    except Exception as e:
        raise RuntimeError(f'Error retrieving parser flags: {e}') from e

