        for action in actions:
            # option_strings is a list of flag strings, empty for positional arguments
            option_strings = getattr(action, "option_strings", [])
            if option_strings:
                flags.extend(option_strings)
    except Exception as exc:
        # Provide a clear error message while preserving the original exception context
