def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    try:
        import argparse
    except Exception:
        # Unable to import argparse; return empty mapping
        return {}
    parser = argparse.ArgumentParser(add_help=False)
    # Allow the user to request help without triggering a SystemExit during parsing
    parser.add_argument('-h', '--help', action='store_true', help='show this help message and exit')
    try:
        # Parse known arguments; unknown ones will be left for subparsers if any
        namespace, _ = parser.parse_known_args(unparsed_arguments)
    except SystemExit as e:
        # argparse may raise SystemExit for --help or parse errors
        # Capture the exit code in the namespace so callers can inspect it
        namespace = argparse.Namespace(exit_code=e.code, error=str(e))
    except Exception as e:
        # Any other exception should result in an error namespace
        namespace = argparse.Namespace(error=str(e))
    return {'global': namespace}

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # Early exit if no arguments were provided
    if not unparsed_arguments:
        return {}

    # The top-level parser is used only for global arguments
    top_parser = argparse.ArgumentParser(add_help=True, exit_on_error=False)
    try:
        # parse known arguments; everything else is returned as the list of unknowns
        global_ns, unknown = top_parser.parse_known_args(unparsed_arguments)
    except Exception:
        # If parsing fails entirely, return an empty result
        return {}

    result = {"global": global_ns}

    # If there are unknown arguments, they might contain a subcommand
    # Find the first non-option argument
    subcommand_index = None
    for idx, token in enumerate(unknown):
        # Treat both Unix-style ('-') and Windows-style ('/') options
        if not token.startswith("-") and not token.startswith("/"):
            subcommand_index = idx
            break

    # If we can't find a subcommand, all unknown arguments are treated as global
    if subcommand_index is None:
        return result

    sub_name = unknown[subcommand_index]
    sub_args = unknown[subcommand_index + 1 :]

    # The parser for the subcommand is generic; it doesn't enforce any arguments.
    # It simply captures whatever follows the subcommand name.
    sub_parser = argparse.ArgumentParser(exit_on_error=False)
    try:
        sub_ns, _ = sub_parser.parse_known_args(sub_args)
    except Exception:
        sub_ns = argparse.Namespace()

    result[sub_name] = sub_ns
    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This
    allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace
    of arguments, a list of remaining arguments not claimed by any subparser).

    Handles malformed input and parser errors gracefully.
    """
    parsed_results = {}
    # Track all tokens that have been consumed by at least one parser
    consumed_global = set()

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
            parsed_results[name] = namespace

            # Count occurrences of each unknown token
            unknown_counts = {}
            for tok in unknown:
                unknown_counts[tok] = unknown_counts.get(tok, 0) + 1

            # Determine which tokens were consumed by this parser
            consumed_by_this = set()
            for tok in unparsed_arguments:
                if unknown_counts.get(tok, 0) > 0:
                    # This token was not consumed; decrement its unknown counter
                    unknown_counts[tok] -= 1
                else:
                    consumed_by_this.add(tok)

            consumed_global.update(consumed_by_this)

        except Exception:
            # In case of parse errors (e.g., SystemExit from ArgumentParser), preserve None
            parsed_results[name] = None

    # Remaining arguments are those not consumed by any parser
    remaining = [tok for tok in unparsed_arguments if tok not in consumed_global]
    return parsed_results, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_results = {}
    unknowns_per_parser = {}
    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
        except SystemExit:
            # If parsing fails (e.g., due to conflicting or missing arguments), treat as no parse.
            namespace = None
            unknown = list(unparsed_arguments)
        parsed_results[name] = namespace
        unknowns_per_parser[name] = set(unknown)

    # Determine remaining args: those not known by any subparser.
    remaining = []
    for token in unparsed_arguments:
        if all(token not in unknowns_per_parser[name] for name in subparsers):
            remaining.append(token)
    return parsed_results, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types and values
    if not isinstance(response, (list, tuple)):
        raise TypeError(f"response must be a list or tuple, got {type(response).__name__}")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError(f"max_results must be a positive integer, got {max_results!r}")

    # Yield slices of the list in pages of size max_results
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Catch any runtime errors during iteration and re-raise
        raise RuntimeError(f"Error during paging: {exc}") from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types and values
    if not isinstance(response, (list, tuple)):
        raise TypeError("response must be a list or tuple")
    try:
        max_results = int(max_results)
    except (TypeError, ValueError):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Generator yielding slices of the response
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        raise TypeError('The argument `dicts` cannot be None')
    result = {}
    try:
        for d in dicts:
            if not isinstance(d, dict):
                raise TypeError(f'Expected dict, got {type(d).__name__}')
            for key, value in d.items():
                if key in result:
                    try:
                        result[key] += value
                    except Exception as exc:
                        raise TypeError(f'Cannot add values for key {key!r}') from exc
                else:
                    result[key] = value
    except TypeError:
        raise
    except Exception as exc:
        raise RuntimeError(f'Error processing input dictionaries: {exc}') from exc
    return result

