def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url_args:
        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dictionary")

    import re

    # Replace {key} style placeholders
    def replace_brace(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        raise KeyError(f"Missing URL argument: {key}")

    try:
        url = re.sub(r'\{([^}]+)\}', replace_brace, url)
    except re.error:
        # If regex fails, just return original url
        pass

    # Replace :key style placeholders
    def replace_colon(match):
        key = match.group(1)
        return str(url_args.get(key, match.group(0)))

    url = re.sub(r':([^/:\?]+)', replace_colon, url)
    return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError(f"url must be a string, got {type(url).__name__}")
    if not isinstance(url_args, dict):
        raise TypeError(f"url_args must be a dict, got {type(url_args).__name__}")

    try:
        return url.format(**url_args)
    except KeyError as e:
        missing_key = e.args[0] if e.args else None
        raise ValueError(f"Missing URL argument: {missing_key}") from None
    except Exception as exc:
        raise ValueError(f"Error formatting URL: {exc}") from None

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if url_args is not None and not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict or None")
    if not url_args:
        return url
    # Patterns for {placeholder} and :placeholder
    import re
    pattern = re.compile(r'\{(\w+)\}|:([A-Za-z0-9_]+)')
    def _replacer(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)
    return pattern.sub(_replacer, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # validate inputs
    if not isinstance(url, str):
        raise TypeError("url must be a str")
