        return url
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    import re

    # pattern matches {key} where key does not contain braces
    pattern = re.compile(r"\{([^{}]+)\}")

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        # if key missing, leave placeholder unchanged
        return match.group(0)

    return pattern.sub(_repl, url)

