def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    Use an absolute path to avoid confusion between relative paths and to detect
    duplicate processing in recursive scenarios.

    Args:
        processed: Set to store absolute pathnames that have been processed.
        path_name: Path to a directory or file. May be string or convertible to string.
        verbose: Boolean flag for verbose output.

    Returns:
        True if the absolute path is already in ``processed``. False otherwise.
    """
    # Validate the input container
    try:
        if not isinstance(processed, set):
            raise TypeError("processed must be a set")
    except Exception as exc:
        if verbose:
            print(f"[was_processed] Invalid 'processed' argument: {exc}")
        return False

    # Convert the path to a string and compute the absolute path
    try:
        path_str = str(path_name)
        abs_path = os.path.abspath(path_str)
    except Exception as exc:
        if verbose:
            print(f"[was_processed] Failed to resolve path '{path_name}': {exc}")
        return False

    # Check if we have already processed this path
    if abs_path in processed:
        if verbose:
            print(f"[was_processed] Path already processed: {abs_path}")
        return True

    # First time seeing this path, add it to the set
    try:
        processed.add(abs_path)
    except Exception as exc:
