def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate alphabet
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols for base conversion.")
    # Validate padding
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("Padding must be an integer or None.")
        if padding < 0:
            raise ValueError("Padding must be non-negative.")
    # Handle negative numbers
    negative = number < 0
    n = abs(number)
    # Convert to given base
    if n == 0:
        result = alphabet[0]
    else:
        digits = []
        try:
            while n:
                n, rem = divmod(n, base)
                digits.append(alphabet[rem])
        except Exception as exc:
            raise ValueError(f"Error during conversion: {exc}") from exc
        digits.reverse()
        result = "".join(digits)
    if negative:
        result = "-" + result
    # Apply padding if requested
    if padding is not None:
        total_length = len(result)
        if negative:
            # Do not pad the negative sign
            total_length -= 1
        if total_length < padding:
            pad = alphabet[0] * (padding - total_length)
            if negative:
                result = "-" + pad + result[1:]
            else:
                result = pad + result
    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError("alphabet must contain at least two symbols")
    base = len(alphabet)

    # Handle padding if specified
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    # Special case: number is zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    # Apply padding if necessary
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

