        if not isinstance(sym, str):
            raise TypeError("alphabet elements must be strings")
        if sym == "":
            raise ValueError("alphabet elements must be non-empty strings")
        digit_map[sym] = idx

    # Handle unary base specially
    if base == 1:
        if any(ch != alphabet[0] for ch in string):
            raise ValueError("string contains invalid symbol for base-1 alphabet")
        return len(string)

    # Convert string to integer using the distinguished base
    result = 0
    for ch in string:
        if ch not in digit_map:
            raise ValueError(f"invalid character '{ch}' in string")
