def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Download a .tar.gz archive from the given URL, extract it into the
    specified destination directory, and return the destination Path.
    Handles downloading errors, extraction errors, and input validation.
    """
    # Input validation
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure destination directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise OSError(f"Unable to create destination directory {destination_path}: {e}") from e

    # Temporary file to store the downloaded archive
    import tempfile
    import tarfile
    try:
        with tempfile.NamedTemporaryFile(delete=False) as tmp_file:
            tmp_path = Path(tmp_file.name)
        # Download the archive
        try:
            with requests.get(url, stream=True, timeout=30) as r:
                r.raise_for_status()
                with open(tmp_path, "wb") as f:
                    for chunk in r.iter_content(chunk_size=8192):
                        if chunk:
                            f.write(chunk)
        except requests.RequestException as e:
            # Clean up the temp file before raising
            tmp_path.unlink(missing_ok=True)
            raise RuntimeError(f"Failed to download archive from {url}: {e}") from e

        # Extract the archive
        try:
            with tarfile.open(tmp_path, mode="r:gz") as tar:
                tar.extractall(path=str(destination_path))
        except tarfile.TarError as e:
            raise RuntimeError(f"Failed to extract archive {tmp_path}: {e}") from e
        finally:
            # Remove the temporary file
            tmp_path.unlink(missing_ok=True)

        return destination_path
    except Exception as e:
        # Ensure temp file is cleaned up in case of unexpected errors
        if 'tmp_path' in locals() and tmp_path.exists():
            try:
                tmp_path.unlink(missing_ok=True)
            except Exception:
                pass
        raise e

def os_is_mac():
    """
    Checks if the OS is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        import sys
        # Primary check: platform string
        if getattr(sys, "platform", "").lower() == "darwin":
            return True
        # Fallback check using os.uname() if available
        if hasattr(os, "uname"):
            uname_result = os.uname()
            if hasattr(uname_result, "sysname") and uname_result.sysname.lower() == "darwin":
                return True
    except Exception:
        # In case of any unexpected error, treat as non-mac
        pass
    return False

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.
    """
    # Helper to transform a glob-like string into a regex pattern
    def glob_to_regex(glob):
        # Use a list for efficient concatenation
        pattern = ['^']
        for char in glob:
            if char == '*':
                pattern.append('.*')
            elif char == '?':
                pattern.append('.')
            else:
                # Escape regex special characters
                if char in ".^$+{}[]|\\()":
                    pattern.append('\\' + char)
                else:
                    pattern.append(char)
        pattern.append('$')
        return ''.join(pattern)

    if not isinstance(item, dict):
        raise TypeError("input must be a dict")
    result = {}
    for key, value in item.items():
        if isinstance(key, str):
            try:
                new_key = glob_to_regex(key)
            except Exception:
                # In case of unexpected errors during pattern conversion,
                # keep the original key.
                new_key = key
        else:
            # Non-string keys are kept unchanged
            new_key = key
        result[new_key] = value
    return result

