def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys, shlex
    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0
    if not isinstance(s, str):
        raise TypeError(f"s must be a str, got {type(s).__name__}")
    if platform == 1:  # POSIX
        try:
            return shlex.split(s)
        except ValueError as exc:
            raise ValueError(f"POSIX split failed: {exc}") from exc
    elif platform == 0:  # Windows
        args = []
        i, n = 0, len(s)
        while i < n:
            # Skip whitespace
            while i < n and s[i].isspace():
                i += 1
            if i >= n:
                break
            # Handle quoted argument
            if s[i] == '"':
                i += 1
                buf = []
                while i < n:
                    c = s[i]
                    if c == '\\':
                        i += 1
                        if i >= n:
                            buf.append('\\')
                            break
                        # In Windows CMD, backslashes are special before a quote
                        if s[i] == '"':
                            # Every pair of backslashes turns into one backslash,
                            # and a trailing quote is removed.
                            # Count backslashes
                            backslashes = 1
                            i += 1
                            while i < n and s[i] == '\\':
                                backslashes += 1
                                i += 1
                            if i < n and s[i] == '"':
                                # Escape backslashes
                                buf.append('\\' * (backslashes // 2))
                                # If odd number of backslashes, the quote is escaped
                                if backslashes % 2 == 1:
                                    buf.append('"')
                                    i += 1
                                else:
                                    # End of quoted section
                                    i += 1
                                    break
                            else:
                                # No following quote: keep backslashes
                                buf.append('\\' * backslashes)
                                continue
                        else:
                            # ordinary escape
                            buf.append(s[i])
                    elif c == '"':
                        i += 1
                        break
                    else:
                        buf.append(c)
                    i += 1
                args.append(''.join(buf))
            else:
                start = i
                while i < n and not s[i].isspace():
                    i += 1
                args.append(s[start:i])
        return args
    else:
        raise ValueError(f"Unsupported platform value: {platform}")

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Build target directory path
    tmp_path_str = str(tmp_path).rstrip("/")
    # Determine default filename (stem of archive file name without extension)
    archive_name = archive_path.rsplit("/", 1)[-1]
    # Remove possible archive suffixes
    suffixes = (".tar.gz", ".tgz", ".tar.bz2", ".tbz", ".tar", ".zip")
    stem = archive_name
    for s in suffixes:
        if archive_name.endswith(s):
            stem = archive_name[: -len(s)]
            break
    else:
        if "." in archive_name:
            stem = archive_name.rsplit(".", 1)[0]
    target_dir = f"{tmp_path_str}/{filename or stem}"
    # Create target directory
    try:
        subprocess.run(["mkdir", "-p", target_dir], check=True)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Failed to create extraction directory {target_dir}") from exc
    # Decide extraction command based on file extension
    try:
        if archive_path.endswith((".tar.gz", ".tgz", ".tar.bz2", ".tbz", ".tar")):
            # use tar
            subprocess.run(
                ["tar", "-xf", archive_path, "-C", target_dir],
                check=True,
            )
        elif archive_path.endswith(".zip"):
            subprocess.run(
                ["unzip", "-qq", archive_path, "-d", target_dir],
                check=True,
            )
        else:
            raise ValueError(f"Unsupported archive format for {archive_path}")
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}") from exc
    # Return file:// URL of extracted repository
    return f"file://{target_dir}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Determine the extraction directory name
    # Remove path and extensions from archive_path to get a base name
    base_name = archive_path.split("/")[-1]  # fallback if no '/'
    # Strip known extensions: .tar.gz, .tgz, .tar.bz2, .zip
    for ext in (".tar.gz", ".tgz", ".tar.bz2", ".zip"):
        if base_name.endswith(ext):
            base_name = base_name[: -len(ext)]
            break
    else:
        # If none of the known extensions match, just strip last suffix
        if "." in base_name:
            base_name = base_name[: base_name.rfind(".")]

    # Use a deterministic extraction directory inside tmp_path
    extraction_dir = f"{tmp_path}/extracted_{base_name}"
    # Ensure extraction directory exists
    try:
        subprocess.run(
            ["mkdir", "-p", extraction_dir],
            check=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
        )
    except Exception as e:
        raise RuntimeError(f"Failed to create extraction directory '{extraction_dir}': {e}")

    # Choose the extraction command based on the archive type
    cmd = None
    if archive_path.endswith((".tar.gz", ".tgz")):
        cmd = ["tar", "--xpath", extraction_dir, "-xzf", archive_path]
    elif archive_path.endswith(".tar.bz2"):
        cmd = ["tar", "--xpath", extraction_dir, "-xjf", archive_path]
    elif archive_path.endswith(".zip"):
        cmd = ["unzip", "-d", extraction_dir, archive_path]
    else:
        raise ValueError(f"Unsupported archive format for '{archive_path}'")

    # Execute extraction
    try:
        subprocess.run(cmd, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as e:
        raise RuntimeError(f"Extraction failed for '{archive_path}': {e}")

    # Return the file URL of the extracted repository directory
    return f"file://{extraction_dir}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """
    Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        # Resolve paths
        archive = pathlib.Path(archive_path).expanduser().resolve()
        if not archive.is_file():
            raise FileNotFoundError(f"Archive not found: {archive}")

        extraction_root = pathlib.Path(tmp_path).expanduser().resolve()
        extraction_root.mkdir(parents=True, exist_ok=True)

        # Determine extraction directory
        if filename:
            extract_dir = extraction_root / filename
            if extract_dir.exists():
                # Ensure a clean extraction path
                shutil.rmtree(extract_dir)
            extract_dir.mkdir(parents=True)
        else:
            # Use a temporary directory if filename not provided
            extract_dir = pathlib.Path(tempfile.mkdtemp(dir=extraction_root))

        # Extract based on archive type
        if archive.suffix in {".gz", ".bz2", ".xz"} and archive.with_suffix("").suffix == ".tar":
            # Handle .tar.gz, .tar.bz2, .tar.xz
            cmd = ["tar", "--directory", str(extract_dir), "-xf", str(archive)]
        elif archive.suffix == ".zip":
            cmd = ["unzip", "-q", str(archive), "-d", str(extract_dir)]
        elif archive.suffix == ".tar":
            cmd = ["tar", "--directory", str(extract_dir), "-xf", str(archive)]
        else:
            raise ValueError(f"Unsupported archive format: {archive.suffix}")

        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        # Locate the git repository root
        repo_dir = None
        for root, dirs, _ in os.walk(extract_dir):
            if ".git" in dirs:
                repo_dir = pathlib.Path(root)
                break
        if repo_dir is None:
            # If no .git found, fall back to the extraction directory
            repo_dir = extract_dir

        return f"file://{repo_dir.resolve()}"

    except (FileNotFoundError, ValueError) as e:
        raise e
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Extraction failed for {archive_path!s}. "
            f"Command: {' '.join(e.cmd)}. "
            f"Stdout: {e.stdout!r}. Stderr: {e.stderr!r}"
        ) from e
    except Exception as e:
        raise RuntimeError(
            f"Unexpected error while preparing repository from {archive_path!s}: {e}"
        ) from e

