    """
    Write the rendered YAML configuration to the specified file, creating any needed
    directories. If the file already exists and overwrite is False, raise a FileExistsError.
    The file will be written with the permissions specified by `mode` (default 0o600).
    """
    try:
        # Resolve absolute path
        path = os.path.abspath(config_filename)
        dir_name = os.path.dirname(path)

        # If file exists and we shouldn't overwrite, abort
        if os.path.exists(path) and not overwrite:
            raise FileExistsError(f"File '{path}' already exists and overwrite is set to False.")

        # Create directories if they do not exist
        if dir_name and not os.path.isdir(dir_name):
            try:
                os.makedirs(dir_name, exist_ok=True)
            except OSError as e:
                raise OSError(f"Failed to create directories '{dir_name}': {e}") from e

        # Write the configuration to the file
        try:
            with open(path, 'w', encoding='utf-8') as f:
                f.write(rendered_config)
        except OSError as e:
            raise OSError(f"Failed to write configuration to '{path}': {e}") from e

        # Set the file permissions
        try:
            os.chmod(path, mode)
        except OSError as e:
            raise OSError(f"Failed to set permissions on '{path}': {e}") from e

    except Exception as exc:
        # Re-raise known exceptions to preserve their class, otherwise wrap in RuntimeError
        if isinstance(exc, (FileExistsError, OSError)):
            raise
        else:
            raise RuntimeError(f"An unexpected error occurred while writing configuration: {exc}") from exc
    return None

