def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """
    Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    # Basic validation
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("image_href must be a non-empty string")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Malformed URL '{image_href}': {exc}") from exc

    scheme = parsed.scheme.lower()
    if scheme not in ("http", "https"):
        raise ValueError(f"Unsupported URL scheme '{scheme}'. Only http and https allowed.")

    netloc = parsed.netloc
    if not netloc:
        # Try to extract netloc from path if missing (e.g., when someone passes a bare URI)
        if parsed.path:
            # If the string started with "//", urlparse sets netloc empty, path contains location; handle that
            if image_href.startswith("://"):
                parts = image_href.split("://", 1)[1].split("/", 1)
                if parts:
                    netloc = parts[0]
                    if len(parts) > 1:
                        parsed = parsed._replace(path="/" + parts[1])
        if not netloc:
            raise ValueError("URL does not contain a net location (host)")

    image_id = parsed.path.lstrip("/")
    if not image_id:
        # If the path ended with no identifier, e.g., trailing slash
        if parsed.query:
            # Use query as id fallback
            image_id = parsed.query
        else:
            raise ValueError("URL path does not contain an image identifier")

    use_ssl = scheme == "https"
    return (image_id, netloc, use_ssl)

