            if overrides and isinstance(overrides, dict):
                for key, val in overrides.items():
                    cfg[key] = val
            # Resolve environment variables
            if resolve_env:
                cfg = _resolve_env(cfg)
            configs[fname] = cfg
        except Exception as exc:
