    Returns the UTF-8 encoded bytes representation of `obj` if it is a string.
    For non-string inputs, returns None. Handles encoding errors gracefully.
    """
    if not isinstance(obj, str):
        return None
    try:
        return obj.encode('utf-8')
    except Exception:
        # In case of any unexpected encoding issue, return None
        return None

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as exc:
            raise ValueError(f"Unable to encode string to UTF-8: {exc}") from exc
    return None

