@classmethod
def from_ticks(cls, ticks, tz=None):
    """
    Create a time from ticks (nanoseconds since midnight).

    :param ticks: nanoseconds since midnight
    :type ticks: int
    :param tz: optional timezone
    :type tz: datetime.tzinfo

    :rtype: Time

    :raises ValueError: if ticks is out of bounds
        (0 <= ticks < 86400000000000)
    """
    if not isinstance(ticks, int):
        raise TypeError("ticks must be an integer")
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks out of bounds (0 <= ticks < 86400000000000)")

    # Calculate hours, minutes, seconds, microseconds from ticks
    total_seconds = ticks // 1_000_000_000
    remaining_nano = ticks % 1_000_000_000

    hour = total_seconds // 3600
    minute = (total_seconds % 3600) // 60
    second = total_seconds % 60
    microsecond = remaining_nano // 1000

    # Try constructing the time object with keyword arguments first
    try:
        return cls(hour=hour, minute=minute, second=second, microsecond=microsecond, tzinfo=tz)
    except TypeError:
        # Fallback to positional arguments if the class does not accept tzinfo keyword
        try:
            return cls(hour, minute, second, microsecond, tz)
        except Exception as exc:
            # If this also fails, re-raise with a clear message
            raise TypeError(f"Failed to create instance from ticks: {exc}") from exc

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
    If an explicit protocol version is provided, the dictionary will contain
    either zero or one items, depending on whether that version is supported.
    If no protocol version is provided, all available versions will be returned.
    Raises TypeError if protocol_version is not a tuple.
    """
    # Grab the mapping of supported protocols that the subclass should
    # provide; use an empty dict as a safe default.
    try:
        supported = getattr(cls, "_SUPPORTED_PROTOCOLS", {})
    except Exception:
        supported = {}

    # Validate explicit protocol_version input.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Return a single-item dict if the handler exists, otherwise empty.
        handler = supported.get(protocol_version)
        return {protocol_version: handler} if handler else {}

    # Return all supported protocol handlers
    return dict(supported)

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Validate the provided protocol_version if one was given
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple or None")

        # Determine the source of supported handlers. Subclasses can override
        # the _protocol_handlers attribute, or we fall back to an empty dict.
        handlers = getattr(cls, "_protocol_handlers", {})

        # Ensure we are working with a plain dictionary for safety
        if not isinstance(handlers, dict):
            # If the attribute is something else, treat it as unsupported
            handlers = {}

        # If a specific version was requested, narrow the result to that
        if protocol_version is not None:
            return (
                {protocol_version: handlers[protocol_version]}
                if protocol_version in handlers
                else {}
            )

        # No specific version requested: return a copy of the entire set
        return handlers.copy()

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(handlers)
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    return {protocol_version: handlers[protocol_version]} if protocol_version in handlers else {}

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Fetch the internal registry of handlers, defaulting to an empty
    # dictionary if not defined (for safety in contexts where the
    # class hasn't populated it yet).
    registry = getattr(cls, "_protocol_handlers", {})
    if protocol_version is None:
        return dict(registry)

    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    # Return a dict with a single entry if the version is supported;
    # otherwise return an empty dict.
    if protocol_version in registry:
        return {protocol_version: registry[protocol_version]}
    return {}

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Attempt to retrieve the mapping of protocol handlers.
    try:
        handlers_map = cls._protocol_handlers
    except AttributeError:
        # If the class does not define _protocol_handlers, return empty dict.
        return {}

    # If a specific protocol version is requested, validate its type.
    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")
        # Fetch the handler for the requested version, if any.
        handler_cls = handlers_map.get(protocol_version)
        return {protocol_version: handler_cls} if handler_cls is not None else {}

    # No specific version requested: return a full copy of the handlers map.
    # Use dict() to create a shallow copy to avoid accidental modifications.
    return dict(handlers_map)

@classmethod
def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    This method provides a convenient way to instantiate a ``Bookmarks`` object
    from an iterable of raw bookmark strings.  The implementation is tolerant
    to a variety of ``values`` inputs and performs basic validation.  If
    ``values`` is ``None`` or an empty iterable an empty ``Bookmarks`` instance
    is returned.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: A populated :class:`Bookmarks` instance
    :raises ValueError: If any element in ``values`` is not a string.
    """
    # Instantiate a new instance of the calling class; allow ``__new__`` to
    # create the object even if ``__init__`` requires no arguments.
    try:
        instance = cls()
    except TypeError as exc:
        # Handle classes that only allow keyword args or a different signature
        try:
            instance = cls.__new__(cls)
        except Exception:
            raise TypeError(
                f"Could not instantiate {cls.__name__} with arguments: {exc}"
            )
        else:
            # If __init__ requires arguments, attempt to call with defaults
            try:
                init_sig = instance.__init__
                init_sig(None)  # type: ignore
            except TypeError:
                # skip; the instance is shippable as is
                pass

    # Store internal representation: if the class already has a ``bookmarks``
    # attribute, preserve it; otherwise create a fresh list.
    if hasattr(instance, "bookmarks"):
        storage = instance.bookmarks
        if not isinstance(storage, list):
            # If the existing type isn't list, replace it with a list
            storage = []
            instance.bookmarks = storage
    else:
        storage = []
        setattr(instance, "bookmarks", storage)

    # Validate input and fill the storage
    if values is None:
        return instance

    if not hasattr(values, "__iter__"):
        raise ValueError("``values`` must be an iterable of strings")

    for raw in values:
        if not isinstance(raw, str):
            raise ValueError(
                f"Bookmark raw value must be a string, got {type(raw).__name__}"
            )
        # Strip surrounding whitespace if desired
        cleaned = raw.strip()
        storage.append(cleaned)

    return instance

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        # Basic validation: ensure we were given something iterable
        if values is None:
            raise TypeError("values must not be None")
        try:
            iterator = iter(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")

        # Collect the valid string values
        raw_list = []
        for raw in iterator:
            if not isinstance(raw, str):
                raise ValueError(
                    f"Each bookmark value must be a string; got {type(raw).__name__}"
                )
            raw_list.append(raw)

        # Attempt to construct a Bookmarks instance from the cleaned list.
        # If the constructor expects something else (e.g. a dict of path => name),
        # callers can adapt this method accordingly.
        return cls(raw_list)

@classmethod
def from_raw_values(cls, values):
    """
    Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    :return: A new instance of ``cls`` populated with the provided bookmarks.
    """
    try:
        # Normalise the input into a list of strings
        if values is None:
            parsed = []
        else:
            # Avoid treating a single string as an iterable of characters
            if isinstance(values, str):
                parsed = [values]
            else:
                parsed = []
                for v in values:
                    if not isinstance(v, str):
                        raise TypeError(
                            f"Bookmark value must be a string; got {type(v).__name__}"
                        )
                    parsed.append(v)

        # Instantiate and return the Bookmarks object
        return cls(parsed)
    except Exception as exc:
        # Wrap any exception into a more descriptive error
        raise ValueError(f"Failed to create Bookmarks from raw values: {exc}") from exc

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    If *seq* is not a sequence but an iterable, materialize it into a list.
    If *bufsize* is provided, only the first *bufsize* items are read from an
    iterable; the rest are discarded.  This behaviour is useful when *seq*
    is a generator or an iterator that may be large or infinite.
    """
    from collections.abc import Sequence, Iterable
    import itertools

    # If seq is None, return it directly.
    if seq is None:
        return seq, type(seq)

    # If seq is already a sequence (including str, bytes, bytearray),
    # return it unchanged.
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # If seq is not iterable, raise a TypeError.
    if not isinstance(seq, Iterable):
        raise TypeError(f"Object of type {type(seq).__name__} is not iterable")

    # At this point, seq is iterable but not a sequence.
    # If a buffer size is requested, read only up to that many items.
    if bufsize is not None:
        try:
            bufsize = int(bufsize)
            if bufsize < 0:
                raise ValueError
        except Exception as exc:
            raise ValueError(f"bufsize must be a non‑negative integer, got {bufsize!r}") from exc
        seq_iter = itertools.islice(seq, bufsize)
    else:
        seq_iter = seq

    # Materialize the iterable into a list.
    seq_list = list(seq_iter)
    return seq_list, type(seq_list)

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Ensure the histogram data exists
        try:
            data = self._data  # we expect a sequence of bin counts
        except AttributeError:
            raise AttributeError("Histogram object has no attribute '_data'")

        def _compute_scale():
            try:
                return sum(data)
            except TypeError:
                # data might be a NumPy array or similar
                try:
                    return data.sum()
                except Exception as exc:
                    raise ValueError("Unable to compute scale from histogram data") from exc

        # When other is None: return the (possibly cached) scale
        if other is None:
            if getattr(self, "_scale", None) is None or recompute:
                self._scale = _compute_scale()
            return self._scale

        # other is a number: we want to rescale the histogram to 'other'
        if not isinstance(other, (int, float)):
            raise TypeError(f"Scale target must be a number, got {type(other).__name__}")

        # Obtain the current scale, recomputing if required
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or recompute:
            current_scale = _compute_scale()
            self._scale = current_scale

        if current_scale == 0:
            raise LenaValueError("Cannot rescale a histogram with zero scale")

        # Compute the scaling factor and apply it to all bins
        factor = other / current_scale
        try:
            if isinstance(data, list):
                self._data = [x * factor for x in data]
            else:
                # Assume array-like supporting multiplication
                self._data = data * factor
        except Exception as exc:
            raise ValueError("Failed to apply scaling factor to histogram data") from exc

        # Update stored scale
        self._scale = other
        return None"

def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute integral if needed
    def _compute_scale():
        # Attempt to use a dedicated integral method if available
        if hasattr(self, "integral") and callable(self.integral):
            return float(self.integral())
        # Fallback: sum over bin contents
        # Try common attributes that may hold bin contents
        contents = None
        if hasattr(self, "bins"):
            # assume bins is iterable of bin objects with 'content' attribute
            try:
                contents = [float(b.content) for b in self.bins]
            except Exception:
                pass
        if contents is None and hasattr(self, "_contents"):
            try:
                contents = [float(c) for c in self._contents]
            except Exception:
                pass
        if contents is None:
            raise AttributeError("Unable to determine bin contents for scale computation.")
        return float(sum(contents))

    # Retrieve or compute current scale
    current_scale = getattr(self, "_scale", None)
    if current_scale is None or recompute:
        # Compute integral and store it
        current_scale = _compute_scale()
        self._scale = current_scale

    # If no target scale provided, just return current scale
    if other is None:
        return current_scale

    # Ensure *other* is numeric
    if not isinstance(other, (int, float)):
        raise TypeError(f"Target scale must be a numeric value, got {type(other).__name__}")

    # Cannot rescale if current scale is zero
    if current_scale == 0:
        raise .LenaValueError("Cannot rescale a histogram with zero scale.")

    # Compute rescaling factor
    factor = float(other) / current_scale

    # Apply factor to all bins
    # Attempt typical bin containers
    if hasattr(self, "bins"):
        for b in self.bins:
            # Assume bin objects have 'content' attribute
            try:
                b.content = float(b.content) * factor
            except Exception:
                pass  # If cannot set, skip
    elif hasattr(self, "_contents"):
        for idx, val in enumerate(self._contents):
            try:
                self._contents[idx] = float(val) * factor
            except Exception:
                pass
    else:
        # If we cannot locate bin contents, raise an error
        raise AttributeError("Unable to locate bin contents for rescaling.")

    # Update stored scale
    self._scale = float(other)
    # Return the new scale for convenience
    return self._scale

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return the current scale if no new value is given
        if other is None:
            return self.scale

        # Ensure the new scale is a numeric value
        if not isinstance(other, (int, float)):
            raise TypeError(f"Scale must be numeric, got {type(other)!r}")

        # The current scale must be known and non‑zero to rescale
        current_scale = getattr(self, "scale", None)
        if current_scale is None or current_scale == 0:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale")

        # Compute scaling factor
        factor = other / current_scale

        # Scale the last coordinate of the data if present
        data = getattr(self, "data", None)
        if data is not None and isinstance(data, (list, tuple)):
            for idx, point in enumerate(data):
                if isinstance(point, (list, tuple)) and len(point) >= 1:
                    try:
                        data[idx] = (*point[:-1], point[-1] * factor)
                    except Exception:
                        pass  # If data is immutable or element cannot be multiplied, ignore

        # Scale the last coordinate of the errors if present
        errors = getattr(self, "errors", None)
        if errors is not None and isinstance(errors, (list, tuple)):
            for idx, err in enumerate(errors):
                if isinstance(err, (list, tuple)) and len(err) >= 1:
                    try:
                        errors[idx] = (*err[:-1], err[-1] * factor)
                    except Exception:
                        pass

        # Update the stored scale
        self.scale = other
        return None

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Get current scale
    if other is None:
        return self._scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError(f"Scale must be a numeric value, got {type(other).__name__}")

    # Ensure existing scale is valid
    try:
        current_scale = self._scale
    except AttributeError as exc:
        raise AttributeError("Scale attribute is missing") from exc

    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale: existing scale is unknown or zero")

    try:
        factor = other / current_scale
    except ZeroDivisionError as exc:
        raise LenaValueError("Cannot rescale due to division by zero") from exc

    # Apply scaling to the fields
    try:
        fields = getattr(self, "fields", None)
        if isinstance(fields, (list, tuple)):
            for item in fields:
                if isinstance(item, (list, tuple)):
                    # Rescale the last coordinate
                    try:
                        item_index = -1
                        old_value = item[item_index]
                        item[item_index] = old_value * factor
                    except (IndexError, TypeError):
                        pass  # Skip items that are not subscriptable or too short
    except Exception:
        # Gracefully ignore any unexpected errors in fields handling
        pass

    # Apply scaling to the errors if present
    try:
        errors = getattr(self, "errors", None)
        if isinstance(errors, (list, tuple)):
            for item in errors:
                if isinstance(item, (list, tuple)):
                    try:
                        item_index = -1
                        old_value = item[item_index]
                        item[item_index] = old_value * factor
                    except (IndexError, TypeError):
                        pass
    except Exception:
        pass

    # Update the stored scale
    self._scale = other
    return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """
    Convert a histogram to a graph representation.
    """
    # Validate histogram input
    try:
        bins = list(hist.bins)  # Support any iterable of bins
    except AttributeError:
        raise TypeError("The provided object does not expose a 'bins' attribute")

    # Default value maker: bin content
    if make_value is None:
        make_value = lambda b: getattr(b, "content", None)

    # Prepare storage for coordinate and values
    coords = []
    values = []

    # First pass: gather coordinates and determine value dimensionality
    dim = None  # number of components per value
    for bin_ in bins:
        # Resolve coordinate
        if not hasattr(bin_, get_coordinate):
            raise AttributeError(f"Histogram bin does not have attribute '{get_coordinate}'")
        coords.append(getattr(bin_, get_coordinate))

        # Get value (may be scalar or sequence)
        try:
            val = make_value(bin_)
        except Exception as exc:
            raise RuntimeError(f"Error applying make_value to bin: {exc}") from exc

        values.append(val)

        # Detect dimensionality
        if isinstance(val, (tuple, list)):
            if dim is None:
                dim = len(val)
            elif dim != len(val):
                raise ValueError("Inconsistent dimensionality returned by make_value")

    # Determine number of fields
    if isinstance(values[0], (tuple, list)):
        result_dim = dim
    else:
        result_dim = 1

    total_fields = 1 + result_dim  # +1 for the coordinate field

    if len(field_names) != total_fields:
        raise ValueError(f"Number of field_names ({len(field_names)}) does not match "
                         f"result dimensionality ({total_fields})")

    # Build graph data structure as a dictionary of field_name -> list
    graph = {field_names[0]: coords}

    if result_dim == 1:
        # Scalar values
        y = [v if not isinstance(v, (tuple, list)) else v[0] for v in values]
        graph[field_names[1]] = y
    else:
        # Multiple components per bin
        # Initialize lists for each component
        component_lists = [[] for _ in range(result_dim)]
        for v in values:
            if not isinstance(v, (tuple, list)):
                raise TypeError("make_value returned a scalar but more fields were expected")
            for i, comp in enumerate(v):
                component_lists[i].append(comp)
        for name, comp_list in zip(field_names[1:], component_lists):
            graph[name] = comp_list

    # Apply scaling
    if scale is True:
        # Use histogram's scale if present
        try:
            graph["scale"] = getattr(hist, "scale")
        except AttributeError:
            graph["scale"] = None
    elif scale is not None:
        graph["scale"] = scale

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
