def determineMetaclass(bases, explicit_mc=None):
    """
    Determine metaclass from 1+ bases and optional explicit __metaclass__.
    Returns a type object that will be used as the metaclass for class creation.
    Raises TypeError if metaclass cannot be determined or conflicts exist.
    """
    # Validate bases
    if not isinstance(bases, (tuple, list)):
        raise TypeError(f"bases must be a tuple or list of types, not {type(bases).__name__}")
    for i, base in enumerate(bases):
        if not isinstance(base, type):
            raise TypeError(f"all bases must be types, element at index {i} is {type(base).__name__}")

    # If no bases: default to type or explicit metaclass
    if not bases:
        return explicit_mc if explicit_mc is not None else type

    # Helper to get metaclass of a base
    def mcs_of(base):
        return type(base)

    # If an explicit metaclass is provided
    if explicit_mc is not None:
        # It must be a type
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit metaclass is not a type: {type(explicit_mc).__name__}")
        # It must be compatible with all base metaclasses
        for base in bases:
            base_mcs = mcs_of(base)
            try:
                if not issubclass(explicit_mc, base_mcs):
                    raise TypeError(f"explicit metaclass {explicit_mc.__name__} is not a subclass of {base_mcs.__name__} for base {base.__name__}")
            except TypeError:
                # issubclass may raise if explicit_mc or base_mcs is not a class
                raise TypeError(f"cannot determine compatibility between {explicit_mc} and {base_mcs}")
        return explicit_mc

    # No explicit metaclass: determine the most derived metaclass from bases
    # Start with the metaclass of the first base
    candidate = mcs_of(bases[0])
    for base in bases[1:]:
        current_mcs = mcs_of(base)
        if issubclass(candidate, current_mcs):
            continue
        if issubclass(current_mcs, candidate):
            candidate = current_mcs
            continue
        # Conflict: neither metaclass is a subclass of the other
        raise TypeError(
            f"metaclass conflict: {candidate.__name__} is not a subclass of {current_mcs.__name__} "
            f"and vice versa"
        )
    # Ensure the final candidate is a subclass of type (always true for a metaclass)
    if not isinstance(candidate, type):
        raise TypeError(f"determined metaclass {candidate} is not a type")
    return candidate

