def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.
    A request is considered a Matrix request if any of the following are true:
    1. The URL path or request path contains the substring '/_matrix'.
    2. The request has a Content-Type header of 'application/json' (case-insensitive)
       and the JSON body contains at least one of the following keys:
          - 'type' and 'sender'  (typical event structure)
          - 'room_id'            (used in many Matrix APIs)
    The function is tolerant of missing attributes and will return False if
    any of the heuristics cannot be evaluated.
    """
    try:
        # 1. Check for Matrix-style path
        path = getattr(request, "url", None) or getattr(request, "path", None)
        if isinstance(path, str) and "/_matrix" in path:
            return True

        # 2. Check headers for JSON content type
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            content_type = headers.get("Content-Type") or headers.get("content-type")
            if content_type and "application/json" in content_type.lower():
                # Attempt to parse JSON body
                body = None
                # Common web frameworks expose a .json() method
                if hasattr(request, "json"):
                    try:
                        body = request.json()
                    except Exception:
                        body = None
                # Some frameworks provide a .get_json() method
                elif hasattr(request, "get_json"):
                    try:
                        body = request.get_json()
                    except Exception:
                        body = None
                # Starlette/FastAPI style: request._json method
                elif hasattr(request, "_json"):
                    try:
                        body = request._json
                    except Exception:
                        body = None

                if isinstance(body, dict):
                    if ("type" in body and "sender" in body) or "room_id" in body:
                        return True
    except Exception:
        # Any unexpected error during inspection means we cannot confirm a Matrix request
        pass

    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    try:
        from datetime import datetime, timezone
    except Exception as exc:
        raise RuntimeError(f"Required datetime modules not available: {exc}") from exc

    # Validate input
    if not isinstance(dt, datetime):
        raise TypeError(f"dt must be a datetime instance, got {type(dt).__name__}")

    # Ensure timezone awareness (assume UTC if naive)
    try:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError(f"Could not convert datetime to UTC: {exc}") from exc

    # Format as ISO 8601 string ending with 'Z' to denote UTC
    try:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    except Exception as exc:
        raise ValueError(f"Formatting failed: {exc}") from exc

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Validate input type
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    try:
        import re

        # Regex to capture http/https URLs (non-whitespace characters following the scheme)
        url_pattern = re.compile(r'(https?://[^\s]+)')

        # Replacement function that wraps the URL in an anchor tag with desired attributes
        def replace_url(match):
            url = match.group(0)
            # Escape double quotes inside the URL (unlikely but safe)
            escaped_url = url.replace('"', '&quot;')
            return f'<a href="{escaped_url}" target="_blank" rel="noopener noreferrer">{escaped_url}</a>'

        # Apply the replacement to the entire text
        return url_pattern.sub(replace_url, text)
    except Exception:
        # In case of any unexpected errors, return the original text unchanged
        return text

