                link_dict = link.attrib.copy()
                # Include text content if present
                if link.text and link.text.strip():
                    link_dict["text"] = link.text.strip()
                links.append(link_dict)
            return {"subject": subject, "links": links}
        except Exception as e:
            raise ValueError(f"Unable to parse Diaspora webfinger document: {e}") from e

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not isinstance(document, str):
        raise TypeError("document must be a string")
    content = document.strip()
    if not content:
        raise ValueError("empty webfinger document")

    # First, try JSON parsing (new format)
    try:
        parsed = json.loads(content)
        if isinstance(parsed, dict):
            return parsed
    except json.JSONDecodeError:
        pass  # fall back to XML parsing

    # If JSON parsing fails, attempt XML (XRD) parsing
    try:
        root = ET.fromstring(content)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid webfinger document: cannot parse XML: {exc}") from exc

    def local_tag(tag: str) -> str:
        """Return the local name part of a qualified tag."""
        return tag.split('}', 1)[-1] if '}' in tag else tag

    subject = None
    aliases: list[str] = []
    links: list[dict] = []

    for elem in root.iter():
        name = local_tag(elem.tag)
        if name == "Subject":
            subject = elem.text or ""
        elif name == "Alias" and elem.text:
            aliases.append(elem.text)
        elif name == "Link":
            # Convert Link attributes to a dictionary
            # Only keep relevant descriptors (href, rel, type, title)
            link_info = {
                k: v for k, v in elem.attrib.items()
                if k in {"rel", "type", "href", "title"}
            }
            if link_info:
                links.append(link_info)

    return {
        "subject": subject,
        "aliases": aliases,
        "links": links,
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    import json, xml.etree.ElementTree as ET
    result: Dict[str, Any] = {}
    if not document:
        return result
    doc = document.strip()
    # Attempt JSON parsing first
    try:
        parsed = json.loads(doc)
        if isinstance(parsed, dict):
            return parsed
    except Exception:
        pass
    # Attempt XML (XRD) parsing
    try:
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        root = ET.fromstring(doc)
        if root.tag.endswith("XRD"):
            subject = root.findtext("xrd:Subject", namespaces=ns)
            if subject:
                result["subject"] = subject
            aliases = [a.text for a in root.findall("xrd:Alias", namespaces=ns)]
            if aliases:
                result["aliases"] = aliases
            links = []
            for link in root.findall("xrd:Link", namespaces=ns):
                ld: Dict[str, str] = {}
                for key in ("rel", "type", "href", "title"):
                    if key in link.attrib:
                        ld[key] = link.attrib[key]
                if ld:
                    links.append(ld)
            if links:
                result["links"] = links
            return result
    except Exception:
        pass
    # If parsing failed, return empty dict
    return result

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Ensure the resource identifier is in "acct:" form
    resource = handle if handle.lower().startswith("acct:") else f"acct:{handle}"
    if "@" not in resource:
        return None
    # Extract domain part, ignoring any port specifier
    try:
        domain = resource.split("@", 1)[1].split(":", 1)[0]
    except Exception:
        return None
    # Construct the webfinger request URL
    import urllib.parse
    import urllib.request
    try:
        query = urllib.parse.quote(resource, safe="")
        urls = [
            f"https://{domain}/.well-known/webfinger?resource={query}",
            f"http://{domain}/.well-known/webfinger?resource={query}"
        ]
        for url in urls:
            try:
                with urllib.request.urlopen(url, timeout=5) as resp:
                    if resp.status == 200:
                        return resp.read().decode("utf-8", errors="ignore")
            except Exception:
                continue
    except Exception:
        pass
    return None

