def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Basic type checks
    if not isinstance(dic, dict):
        raise TypeError("The 'dic' argument must be a dictionary.")
    if key is None:
        raise ValueError("The primary 'key' cannot be None.")
    if not isinstance(key, str):
        # Coerce other types to str if possible
        try:
            key = str(key)
        except Exception:
            raise TypeError("All key components must be strings or convertible to strings.")

    # Build the full key chain
    key_chain = [key]
    for k in keys:
        if k is None:
            raise ValueError("Nested keys cannot be None.")
        if not isinstance(k, str):
            try:
                k = str(k)
            except Exception:
                raise TypeError("All key components must be strings or convertible to strings.")
        key_chain.append(k)

    current = dic
    for idx, subkey in enumerate(key_chain):
        # Ensure we are working with dictionaries along the path
        if idx == len(key_chain) - 1:
            # Final key: insert the value
            try:
                current[subkey] = val
            except Exception as exc:
                raise RuntimeError(f"Failed to set value for key '{subkey}': {exc}")
        else:
            # Intermediate key: descend into nested dict
            if subkey not in current:
                # Create a new nested dictionary if missing
                current[subkey] = {}
            elif not isinstance(current[subkey], dict):
                # Existing value is not a dict; cannot nest under it
                raise ValueError(f"Cannot nest under key '{subkey}' because it is not a dictionary.")
            # Move to the nested dict
            current = current[subkey]

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    # Validate that dic is a dictionary
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary.")
    # Build the full key chain
    if isinstance(key, (list, tuple)):
        # The user passed the entire chain as the first argument
        key_chain = list(key)
        if keys:
            # If additional keys were also supplied, append them
            key_chain.extend(keys)
    else:
        key_chain = [key] + list(keys)
    if not key_chain:
        raise ValueError("At least one key must be provided.")
    # Traverse or create nested dictionaries
    current = dic
    for k in key_chain[:-1]:
        if not isinstance(k, (str, int, float, bool, type(None))):
            raise TypeError(f"Unsupported key type: {type(k).__name__}")
        # If key exists but is not a dict, replace it with a new dict
        if k in current:
            if not isinstance(current[k], dict):
                current[k] = {}
        else:
            current[k] = {}
        current = current[k]
    # Insert the final key/value pair
    last_key = key_chain[-1]
    if not isinstance(last_key, (str, int, float, bool, type(None))):
        raise TypeError(f"Unsupported key type: {type(last_key).__name__}")
    current[last_key] = val

