        - If a string, it is interpreted as a filename pattern.  If the string
          contains glob‑metacharacters (`*`, `?`, `[`) the file is matched
          using :func:`fnmatch.fnmatch`.  Otherwise an exact name match is
          performed.
      If ``spec_option`` is ``None`` all files are returned.

    Returns
    -------
    list of str
        List of absolute file paths that match ``spec_option``.
    """
    # Dynamically import required modules without top‑level import statements
    _os = __import__('os')
    _fnmatch = __import__('fnmatch')

    results = []

    try:
        dirs = list(settings_dirs)
    except TypeError:
        raise TypeError("settings_dirs must be an iterable of directory paths")

    # Validate spec_option
    if spec_option is not None and not (callable(spec_option) or isinstance(spec_option, str)):
        raise TypeError("spec_option must be None, a string, or a callable")

    has_glob = False
    if isinstance(spec_option, str):
        # Detect glob characters
        for c in '*?[':
            if c in spec_option:
                has_glob = True
                break

    for d in dirs:
        try:
            if not isinstance(d, str):
                continue
            if not _os.path.isdir(d):
                continue
            try:
                entries = _os.listdir(d)
            except (PermissionError, OSError):
                continue
            for name in entries:
                try:
                    full_path = _os.path.join(d, name)
                    if not _os.path.isfile(full_path):
                        continue
                except (OSError, TypeError):
                    continue
                match = False
                if spec_option is None:
                    match = True
                elif callable(spec_option):
                    try:
                        match = bool(spec_option(name))
                    except Exception:
                        match = False
                elif isinstance(spec_option, str):
                    if has_glob:
                        match = _fnmatch.fnmatch(name, spec_option)
                    else:
                        match = (name == spec_option)
                if match:
                    results.append(_os.path.abspath(full_path))
        except Exception:
            # Skip problematic directory entries silently
            continue

    return results

def list_of_file_names(settings_dirs, spec_option):
    """
    Return a list of file names from the provided settings directories.

    Parameters:
    settings_dirs: list or string of directory paths to search.
    spec_option: optional string pattern to filter file names (e.g., '*.ini').

    Returns:
    A list of file names (not full paths) that exist in the specified directories and match the pattern.
    If a directory does not exist or is not readable, it is skipped.
    """
    import os
    import fnmatch

    # Normalise settings_dirs to list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        raise TypeError(f"settings_dirs must be a string or a list/tuple of strings, got {type(settings_dirs).__name__}")

    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError(f"spec_option must be None or a string, got {type(spec_option).__name__}")

    file_names = []

    for dir_path in dirs:
        if not isinstance(dir_path, str):
            # skip invalid path entries
            continue
        try:
            if not os.path.isdir(dir_path):
                # skip non directories
                continue
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                try:
                    if not os.path.isfile(full_path):
                        continue
                    if spec_option is None or fnmatch.fnmatch(entry, spec_option):
                        file_names.append(entry)
                except OSError:
                    # Skip files that cannot be accessed
                    continue
        except (OSError, PermissionError):
            # Skip directories that cannot be accessed
            continue

    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        os = __import__("os")
    except Exception:
        return []

    # Normalise settings_dirs to a list
    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        return []

    # Normalise spec_option to a list of extensions
    if isinstance(spec_option, (list, tuple)):
        extensions = [ext.lower().lstrip(".") for ext in spec_option if isinstance(ext, str)]
    elif isinstance(spec_option, str):
        extensions = [spec_option.lower().lstrip(".")]
    else:
        extensions = []

    matched_files = []

    for d in dirs:
        try:
            if not os.path.isdir(d):
                continue
        except Exception:
            continue
        try:
            entries = os.listdir(d)
        except Exception:
            continue
        for name in entries:
            try:
                full_path = os.path.join(d, name)
                if os.path.isfile(full_path):
                    if extensions:
                        # Check file extension (case-insensitive)
                        ext = name.split(".")[-1].lower()
                        if ext in extensions:
                            matched_files.append(full_path)
                    else:
                        # No filter, include all files
                        matched_files.append(full_path)
            except Exception:
                continue
    return matched_files

@classmethod
def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    import os
    config = {}
    # Determine the config file path, default to 'ansible.cfg' if none specified
    config_path = os.getenv('ANSIBLE_CONFIG', 'ansible.cfg')
    try:
        with open(config_path, 'r') as f:
            for line in f:
                line = line.strip()
                # Skip empty lines and comments
                if not line or line.startswith('#'):
                    continue
                # Parse key=value pairs
                if '=' in line:
                    key, val = line.split('=', 1)
                    config[key.strip()] = val.strip()
    except FileNotFoundError:
        # If the config file does not exist, return an empty dictionary
        return {}
    except PermissionError as e:
        raise RuntimeError(f"Permission denied while reading Ansible config '{config_path}': {e}")
    except Exception as e:
        raise RuntimeError(f"Unexpected error while reading Ansible config '{config_path}': {e}")
    return config

