    if not isinstance(argument_name, str):
        raise TypeError(
            f"argument_name must be a string, got {type(argument_name).__name__}"
        )

    # Attempt to locate the options dictionary; it could be stored under
    # different attribute names depending on how `self` was constructed.
    options_mapping = getattr(self, "_options", None)
    if options_mapping is None:
        options_mapping = getattr(self, "commands", None)

    # If the mapping is not a dictionary, we cannot proceed.
    if not isinstance(options_mapping, dict):
        return None

    # Retrieve the option specifications for the command.
    command_options = options_mapping.get(command_name)
    if not isinstance(command_options, dict):
        return None

    # Return the specification for the requested argument, or None if not found.
    return command_options.get(argument_name)

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        silent = []
        try:
            if args is None:
                return silent
            # Handle argparse.Namespace or objects with __dict__
            if isinstance(args, dict):
                items = args.items()
            elif hasattr(args, '__dict__'):
                items = args.__dict__.items()
            elif hasattr(args, 'keys'):  # Other mapping types
                items = args.items()
            else:
                # Assume iterable of (key, value) tuples
                items = args
            for key, value in items:
                if value is None:
                    silent.append(key)
        except Exception:
            # In case of unexpected structure, return empty list
            return silent
        return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Ensure args is a mapping
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    # Retrieve the required argument names; default to an empty iterable if not defined
    required = getattr(self, 'required_args', None)
    if required is None:
        return

    if not isinstance(required, (list, tuple, set)):
        raise TypeError("required_args must be a list, tuple, or set")

    # Determine which required keys are missing or have None values
    missing = [name for name in required if name not in args or args[name] is None]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec,
                                       args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required_args = []

    # Ensure inputs are usable
    if not isinstance(options_spec, (list, tuple)):
        return required_args
    if not isinstance(args, dict):
        args = {}

    for opt in options_spec:
        try:
            cond = opt.get('required_when')
            if cond is None:
                continue

            matched = False
            if callable(cond):
                # If the condition is a callable, call it with the args dict
                try:
                    matched = bool(cond(args))
                except Exception:
                    matched = False
            elif isinstance(cond, str):
                # Prepare a restricted eval environment
                # expose args values as local identifiers and the args dict itself
                local_vars = {}
                for k, v in args.items():
                    if isinstance(k, str) and k.isidentifier():
                        local_vars[k] = v
                local_vars['args'] = args
                try:
                    matched = bool(eval(cond, {}, local_vars))
                except Exception:
                    matched = False
            else:
                # Unsupported condition type
                matched = False

            if matched:
                name = opt.get('fullname') or opt.get('name')
                if name:
                    required_args.append(name)
        except Exception:
            # Skip any problematic option without raising
            continue

    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """
        List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required_args = []
        for opt in options_spec or []:
            # an option spec can be a dict with at least a ``name`` key
            if not isinstance(opt, dict):
                continue
            opt_name = opt.get("name")
            if not opt_name:
                continue

            cond = opt.get("required_when")
            if cond is None:
                continue

            matched = False
            try:
                if isinstance(cond, str):
                    # If the condition is a comma‑separated list of command names,
                    # check for membership first.
                    if "," in cond:
                        commands = [c.strip() for c in cond.split(",")]
                        if command_name in commands:
                            matched = True
                        else:
                            # fall back to evaluating the string as an expression
                            matched = bool(eval(cond, {"__builtins__": None}, args))
                    else:
                        # try to evaluate the condition in the environment of the
                        # provided args; the condition may reference keys of args
                        matched = bool(eval(cond, {"__builtins__": None}, args))
                elif callable(cond):
                    # condition may be a function that accepts the args dict
                    matched = bool(cond(args))
                else:
                    # unsupported type: ignore
                    matched = False
            except Exception:
                # any error in evaluation results in the condition not matching
                matched = False

            if matched:
                required_args.append(opt_name)

        return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []

    for opt in options_spec:
        # Support both dicts and objects with attributes
        try:
            name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
            cond = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        except Exception:
            # If an option is malformed we simply skip it
            continue

        if not name or cond is None:
            continue

        matched = False

        try:
            # Callable condition
            if callable(cond):
                matched = bool(cond(args))

            # Dictionary mapping option names to expected values
            elif isinstance(cond, dict):
                matched = True
                for key, expected in cond.items():
                    if key not in args:
                        matched = False
                        break
                    actual = args[key]
                    if isinstance(expected, (list, tuple, set)):
                        if actual not in expected:
                            matched = False
                            break
                    else:
                        if actual != expected:
                            matched = False
                            break

            # List/tuple of (key, expected) pairs
            elif isinstance(cond, (list, tuple)):
                matched = True
                for item in cond:
                    if not isinstance(item, (list, tuple)) or len(item) != 2:
                        matched = False
                        break
                    key, expected = item
                    if key not in args:
                        matched = False
                        break
                    actual = args[key]
                    if isinstance(expected, (list, tuple, set)):
                        if actual not in expected:
                            matched = False
                            break
                    else:
                        if actual != expected:
                            matched = False
                            break

            # Boolean condition
            elif isinstance(cond, bool):
                matched = cond

        except Exception:
            # If evaluating the condition raises, treat it as not matched
            matched = False

        if matched:
            required.append(name)

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    Return a list of option names that have ``required_when`` conditions
    satisfied by the current command name or by the supplied arguments.

    Parameters
    ----------
    command_name : str
        The current command name.
    options_spec : list
        A list of option specifications; each specification is a dict
        that may contain a ``required_when`` key.
    args : dict
        The parsed input arguments.  This is passed to any callable
        ``required_when`` condition.

    Returns
    -------
    list
        Names of the options whose ``required_when`` condition is true.
    """
    # Defensive checks
    if not isinstance(command_name, str):
        command_name = ""
    if not isinstance(options_spec, (list, tuple)):
        return []

    required = []
    for opt in options_spec:
        try:
            # Option name can be keys like 'name', 'long', or 'short'.
            name = opt.get("name") or opt.get("long") or opt.get("short")
            if not name:
                continue  # can't identify without a name

            cond = opt.get("required_when")
            if cond is None:
                continue  # no conditional requirement

            # Determine if the condition holds
            is_required = False
            if callable(cond):
                try:
                    is_required = bool(cond(args))
                except Exception:
                    is_required = False
            elif isinstance(cond, (list, tuple, set)):
                # Treat list of command names
                is_required = command_name in cond
            elif isinstance(cond, dict):
                # Support {"commands": [...]} or {"command": "name"}
                commands = cond.get("commands", cond.get("command"))
                if isinstance(commands, (list, tuple, set)):
                    is_required = command_name in commands
                else:
                    try:
                        is_required = bool(commands)
                    except Exception:
                        is_required = False
            else:
                # Treat any truthy value as a condition
                try:
                    is_required = bool(cond)
                except Exception:
                    is_required = False

            if is_required:
                required.append(name)
        except Exception:
            # Ignore malformed option specs and continue
            continue

    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        name = opt.get('name')
        cond = opt.get('required_when')
        if cond:
            matched = False
            try:
                # If the condition is a boolean value, use it directly
                if isinstance(cond, bool):
                    matched = cond
                elif callable(cond):
                    # Try to call with (command_name, args) first
                    try:
                        matched = cond(command_name, args)
                    except Exception:
                        # Then try with just args
                        try:
                            matched = cond(args)
                        except Exception:
                            # Finally try with no arguments
                            matched = cond()
                else:
                    # If it's not callable, attempt to evaluate it as an expression
                    matched = eval(str(cond), {}, {'args': args, 'command_name': command_name})
            except Exception:
                matched = False
            if matched and name:
                required.append(name)
    return required

