def validate_length_args(self, args):
    """
    Check if the value of arguments is not longer than the length specified.

    The method expects ``args`` to be a mapping of argument names to values. For
    each string value, it checks the length against a maximum length that can be
    specified in three ways:

    1. As an attribute on ``self`` named ``<arg_name>_max_length``.
    2. As a dictionary stored in ``self.max_lengths`` that maps argument names
       to maximum lengths.
    3. As a general ``self.max_length`` that applies to all arguments.

    If none of these mechanisms provide a maximum length for a given argument, the
    check is skipped for that value.

    Parameters
    ----------
    args : Mapping
        Mapping of argument names to their values.

    Raises
    ------
    TypeError
        If ``args`` is not a mapping.
    ValueError
        If any string value exceeds its configured maximum length.
    """
    if args is None:
        return

    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")

    for name, value in args.items():
        if value is None:
            continue

        # Helper to determine the maximum length for a given argument
        def get_max_len() -> int | None:
            # Attribute that may be set as <name>_max_length
            attr = f"{name}_max_length"
            if hasattr(self, attr):
                return getattr(self, attr)
            # Mapping of known max lengths
            if hasattr(self, "max_lengths") and isinstance(self.max_lengths, dict):
                return self.max_lengths.get(name)
            # Default max_length
            return getattr(self, "max_length", None)

        max_len = get_max_len()

        # Validate single string value
        if isinstance(value, str):
            if max_len is not None and len(value) > max_len:
                raise ValueError(
                    f"Argument '{name}' value length {len(value)} exceeds maximum allowed {max_len}"
                )

        # Validate a list or tuple of strings
        elif isinstance(value, (list, tuple)):
            if max_len is not None:
                for idx, item in enumerate(value):
                    if isinstance(item, str) and len(item) > max_len:
                        raise ValueError(
                            f"Argument '{name}[{idx}]' value length {len(item)} exceeds maximum allowed {max_len}"
                        )

        # For other types (e.g., int, float), skip length validation
        else:
            continue
    return None

