        if isinstance(value, (list, tuple, set)):
            invalid_values = [v for v in value if v not in valid_values]
            if invalid_values:
                msg = (
                    f"Invalid value(s) {invalid_values!r} for argument '{arg_name}'. "
                    f"Valid choices are {valid_values!r}."
                )
                raise ValueError(msg)
        else:
            if value not in valid_values:
                msg = (
                    f"Invalid value {value!r} for argument '{arg_name}'. "
                    f"Valid choices are {valid_values!r}."
                )
                raise ValueError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments, expected to be a mapping (dict or argparse.Namespace).
    """
    # Access the mapping of argument names to allowed values.
    try:
        choices = getattr(self, 'choices', {})
    except Exception as exc:
        raise ValueError("Cannot access 'choices' attribute for validation.") from exc

    # Ensure `args` is a mapping; support argparse.Namespace by converting via vars().
    if hasattr(args, '__dict__'):
        try:
            args = vars(args)
        except Exception:
            pass
    if not isinstance(args, dict):
        raise TypeError(f"'args' must be a mapping (dict or Namespace), got {type(args).__name__}")

    if not isinstance(choices, dict):
        raise ValueError(f"'choices' must be a dict mapping argument names to valid options, got {type(choices).__name__}")

    for key, val in args.items():
        # Skip validation for arguments without defined choices.
        if key not in choices:
            continue

        valid = choices[key]
        # Normalise valid to a set for efficient membership tests.
        try:
            valid_set = set(valid)
        except Exception:
            # If conversion to set fails, leave as is and rely on 'in' semantics.
            valid_set = valid

        # Skip None values (often used to denote "no selection").
        if val is None:
            continue

        # Handle multi‑choice values: lists, tuples, or sets of selected choices.
        if isinstance(val, (list, tuple, set)):
            for item in val:
                if item not in valid_set:
                    raise ValueError(
                        f"Invalid choice for argument '{key}': "
                        f"'{item}'. Expected one of {valid_set}."
                    )
        else:
            # Single value validation.
            if val not in valid_set:
                raise ValueError(
                    f"Invalid choice for argument '{key}': "
                    f"'{val}'. Expected one of {valid_set}."
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: a dictionary with keys 'value', 'min', 'max' or a sequence
                 containing these items in order (min, max, value).
    :return: True when the value is within the inclusive range.
    :raises ValueError: if arguments are missing, non‑numeric, or the value
                        falls outside the specified bounds.
    """
    try:
        if isinstance(args, dict):
            value = args.get("value")
            min_val = args.get("min")
            max_val = args.get("max")
        elif isinstance(args, (list, tuple)) and len(args) >= 3:
            min_val, max_val, value = args[0], args[1], args[2]
        else:
            raise ValueError(
                "Args must be a dict with keys 'min', 'max', 'value' "
                "or a sequence of at least three items."
            )

        # Ensure all are numeric (int, float, or complex; exclude bool)
        if not all(
            isinstance(v, (int, float, complex)) and not isinstance(v, bool)
            for v in (value, min_val, max_val)
        ):
            raise ValueError("Arguments 'value', 'min', and 'max' must be numeric.")

        if min_val > max_val:
            raise ValueError("Minimum value cannot be greater than maximum value.")

        if not (min_val <= value <= max_val):
            raise ValueError(
                f"Value {value} is outside the allowed range [{min_val}, {max_val}]."
            )

        return True

    except Exception as exc:
        raise ValueError(f"Invalid arguments for min/max validation: {exc}") from exc

