    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Retrieve the minimum and maximum values from the instance. Raise an
    # AttributeError if they are missing so callers know the validation
    # cannot proceed.
    try:
        min_val = getattr(self, "min_value")
        max_val = getattr(self, "max_value")
    except AttributeError as exc:
        raise AttributeError("This object must have 'min_value' and 'max_value' attributes for validation.") from exc

    # Normalize the input into an iterable of values. Only lists/tuples
    # and dictionaries are supported.
    if isinstance(args, (list, tuple)):
        values = args
    elif isinstance(args, dict):
        values = args.values()
    else:
        raise TypeError("`args` must be a list, tuple, or dict representing values to validate.")

    # Iterate over each value, ensuring it can be cast to float and lies
    # between the configured bounds (inclusive). If any validation fails,
    # raise ValueError with a helpful message.
    for idx, val in enumerate(values):
        try:
            numeric_val = float(val)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Argument at position {idx} (value: {val!r}) is not numeric.") from exc

        if not (min_val <= numeric_val <= max_val):
            raise ValueError(
                f"Value {numeric_val} out of bounds [{min_val}, {max_val}]."
            )

    # Return True to indicate all values passed the validation.
    return True

