        }
        return complex_type
    except Exception as exc:
        # Provide a clear error message while preserving traceback for debugging
        raise ValueError(f"Failed to create complex argument type: {exc}") from None

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        try:
            # Validate input types
            if not isinstance(subcommand, str):
                raise TypeError("subcommand must be a string")
            if not isinstance(type_name, str):
                raise TypeError("type_name must be a string")
            if not isinstance(option_name, str):
                raise TypeError("option_name must be a string")
            if spec_option is not None and not isinstance(spec_option, dict):
                raise TypeError("spec_option must be a dict or None")

            # Construct a simple representation of the complex type
            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "spec_option": spec_option
            }
            return complex_type
        except Exception as e:
            raise RuntimeError(f"Failed to create complex argument type: {e}") from e

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                spec_option):
    """
    Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications (dict of attributes)
    :return: the complex type instance
    """
    # Basic argument validation
    if not isinstance(subcommand, str) or not subcommand:
        raise TypeError("subcommand must be a non-empty string")
    if not isinstance(type_name, str) or not type_name:
        raise TypeError("type_name must be a non-empty string")
    if not isinstance(option_name, str) or not option_name:
        raise TypeError("option_name must be a non-empty string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dictionary")

    # Dynamically create a new type with attributes from spec_option
    try:
        # Define __init__ method for the new class
        def _init(self, **kwargs):
            for key, value in kwargs.items():
                setattr(self, key, value)

        # Define a readable __repr__ for debugging purposes
        def _repr(self):
            attrs = ", ".join(f"{k}={getattr(self, k)!r}" for k in self.__dict__)
            return f"<{type_name} {attrs}>"

        # Construct the new type
        kwargs = {
            "__module__": __name__,
            "__init__": _init,
            "__repr__": _repr,
        }
        dynamic_cls = type(type_name, (object,), kwargs)

        # Create an instance of the dynamic class, passing the spec_option dict
        instance = dynamic_cls(**spec_option)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to create complex argument type '{type_name}': {exc}"
        ) from exc

    return instance

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control, nested, and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list/dict of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    # Normalise the input to an iterable of (key, value) pairs.
    if args is None:
        return control_args, nested_args
    if hasattr(args, "items"):
        items = list(args.items())
    elif isinstance(args, (list, tuple)):
        items = []
        for elem in args:
            if isinstance(elem, tuple) and len(elem) == 2:
                items.append(elem)
            elif hasattr(elem, "key") and hasattr(elem, "value"):
                items.append((elem.key, elem.value))
    elif hasattr(args, "__dict__"):
        items = list(vars(args).items())
    else:
        # If args is a single value, we cannot process it.
        return control_args, nested_args

    for key, value in items:
        if not isinstance(key, str):
            # For non-string keys, treat them as nested.
            nested_args[key] = value
            continue
        lc_key = key.lower()
        if lc_key.startswith("control."):
            control_args[key] = value
        else:
            # All other keys are considered nested, including custom ones.
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """
        Split input arguments into control arguments and nested arguments.
        Control arguments are used to manage IR behavior and are not included
        in the generated spec YAML. Nested arguments (including any custom
        Ansible variables) are used by playbooks and are written into the YAML.
        This method accepts either a mapping (dict) of arguments or an
        iterable of strings in the form ``key=value``. It returns a tuple
        ``(control_args, nested_args)`` where each element is a dict.
        """
        # Validate input
        if args is None:
            return {}, {}
        if isinstance(args, dict):
            arg_items = args.items()
        elif isinstance(args, (list, tuple, set)):
            # allow iterables of key=value strings
            arg_items = []
            for item in args:
                if not isinstance(item, str):
                    raise TypeError("Argument list must contain strings 'key=value'.")
                if "=" not in item:
                    raise ValueError(f"Argument '{item}' is not in 'key=value' format.")
                key, _, value = item.partition("=")
                arg_items.append((key.strip(), value.strip()))
        else:
            raise TypeError("args must be a dict or an iterable of 'key=value' strings.")

        # Determine which keys are control arguments.  Subclasses may
        # provide a ``CONTROL_ARGS`` set or list; if not, we treat all
        # keys as nested.
        control_keys = getattr(self, "CONTROL_ARGS", set())
        if isinstance(control_keys, (list, tuple)):
            control_keys = set(control_keys)

        control_args = {}
        nested_args = {}

        for key, value in arg_items:
            if key in control_keys:
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments into control and nested.

        Parameters
        ----------
        args : dict | list | tuple
            Collected list or mapping of arguments.

        Returns
        -------
        tuple(dict, dict)
            Two flat dictionaries: (control_args, nested_args).
        """
        control_args = {}
        nested_args = {}

        # Determine the items to process
        if isinstance(args, dict):
            items = args.items()
        elif isinstance(args, (list, tuple)):
            items = []
            for item in args:
                if isinstance(item, str):
                    if "=" in item:
                        key, val = item.split("=", 1)
                        items.append((key.strip(), val.strip()))
                    else:
                        # Flag-like argument without a value: set to True
                        items.append((item.strip(), True))
                else:
                    raise ValueError(
                        f"Unsupported argument type {type(item).__name__} in list; expected str."
                    )
        else:
            raise TypeError(
                f"Unsupported args type {type(args).__name__}; expected dict, list or tuple."
            )

        # Split into control and nested based on key prefix
        for key, val in items:
            if not isinstance(key, str):
                raise ValueError(f"Argument key must be a string, got {type(key).__name__}")
            trimmed_key = key.lstrip("-_")  # optionally strip leading dashes/underscores
            if trimmed_key.lower().startswith("control"):
                control_args[key] = val
            else:
                nested_args[key] = val

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Defensive copy and normalisation
    if args is None:
        return {}, {}

    # Accept dict input for convenience
    if isinstance(args, dict):
        args_list = []
        for k, v in args.items():
            if isinstance(v, bool):
                args_list.append(f"--{k}")
            else:
                args_list.append(f"--{k}={v}")
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        # Unsupported type; return empty
        return {}, {}

    control_args = {}
    nested_args = {}

    i = 0
    while i < len(args_list):
        token = args_list[i]
        # Skip positional arguments that are not flags
        if not token.startswith("--"):
            i += 1
            continue

        # Separate key and value (e.g., --key=value or --key value)
        try:
            if "=" in token:
                key, val = token[2:].split("=", 1)
            else:
                key = token[2:]
                # Attempt to fetch next argument as value if it is not a flag
                if i + 1 < len(args_list) and not args_list[i + 1].startswith("--"):
                    val = args_list[i + 1]
                    i += 1
                else:
                    # Boolean flag
                    val = True
        except Exception:
            # Malformed token; skip it
            i += 1
            continue

        # Classify based on key prefix
        if key.startswith("control"):
            control_args[key] = val
        elif key.startswith("custom"):
            # Store custom arguments under a reserved sub-dict for clarity
            nested_args.setdefault("custom", {})[key] = val
        else:
            nested_args[key] = val

        i += 1

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of ``key=value`` strings representing extra variables
        :return: The extended dictionary
        :raises TypeError: If ``vars_dict`` is not a dictionary
        :raises RuntimeError: If any unexpected error occurs while processing
        """
        # Validate the base dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        # Nothing to merge
        if not extra_vars:
            return vars_dict

        try:
            for item in extra_vars:
                # Skip non-string items (they cannot be parsed as key=value)
                if not isinstance(item, str):
                    continue

                # Split only on the first '='
                if '=' not in item:
                    continue

                key, value = item.split('=', 1)
                key = key.strip()
                value = value.strip()

                # Only update if the key is non-empty
                if key:
                    vars_dict[key] = value
        except Exception as exc:
            # Wrap any unexpected exception in a RuntimeError for clarity
            raise RuntimeError(f"Error while merging extra variables: {exc}") from exc

        return vars_dict

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")
        if extra_vars is None:
            return vars_dict
        # If extra_vars is a dict itself, just update
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict
        # Ensure we can iterate over extra_vars
        try:
            iterator = iter(extra_vars)
        except TypeError:
            raise TypeError("extra_vars must be an iterable of strings, dicts, tuples or None")
        for item in iterator:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, tuple) and len(item) == 2:
                key, val = item
                vars_dict[key] = val
            elif isinstance(item, str):
                if '=' in item:
                    key, val = item.split('=', 1)
                    vars_dict[key] = val
                else:
                    # Treat as a flag: key -> True
                    vars_dict[item] = True
            else:
                # Ignore other types
                pass
        return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The merged dictionary (modified in place)
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Normalise the extra_vars argument to an iterable
    if isinstance(extra_vars, str):
        extra_vars = [extra_vars]
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a list, tuple, or string")

    for item in extra_vars:
        if item is None:
            continue

        # If an item is a mapping, merge it directly
        if isinstance(item, dict):
            vars_dict.update(item)
            continue

        # If an item is a string, expect ``key=value`` format
        if isinstance(item, str):
            if "=" not in item:
                continue  # skip malformed entries
            key, val = item.split("=", 1)
            key = key.strip()
            val = val.strip()
            # Attempt to interpret the value
            try:
                import ast
                parsed_val = ast.literal_eval(val)
            except Exception:
                # Fallback for values that aren't valid Python literals
                parsed_val = val
            vars_dict[key] = parsed_val
            continue

        # Unsupported item types are ignored; adjust as needed
    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    for var_item in extra_vars:
        if not isinstance(var_item, str):
            continue
        if "=" not in var_item:
            continue
        key, value = var_item.split("=", 1)
        key = key.strip()
        value = value.strip()
        if not key:
            continue
        # Interpret common string representations of booleans and numbers
        lower_val = value.lower()
        if lower_val in ("true", "yes", "on"):
            parsed_val = True
        elif lower_val in ("false", "no", "off"):
            parsed_val = False
        else:
            try:
                parsed_val = int(value)
            except ValueError:
                try:
                    parsed_val = float(value)
                except ValueError:
                    # Strip surrounding quotes if present
                    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
                        parsed_val = value[1:-1]
                    else:
                        parsed_val = value
        vars_dict[key] = parsed_val
    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """
    Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict

    def _merge_mapping(mapping):
        for k, v in mapping.items():
            if isinstance(k, str):
                vars_dict[k] = v

    def _merge_pair(pair_str):
        if '=' in pair_str:
            key, value = pair_str.split('=', 1)
            key = key.strip()
            value = value.strip()
            if key:
                vars_dict[key] = value

    def _merge_from_str(s):
        # Split by comma first, then by whitespace to handle both delimiters
        for part in s.split(','):
            for token in part.split():
                _merge_pair(token)

    if isinstance(extra_vars, dict):
        _merge_mapping(extra_vars)
    elif isinstance(extra_vars, str):
        _merge_from_str(extra_vars)
    elif isinstance(extra_vars, (list, tuple, set)):
        for item in extra_vars:
            if isinstance(item, dict):
                _merge_mapping(item)
            elif isinstance(item, str):
                _merge_from_str(item)
            else:
                # Unsupported item in the collection; ignore it gracefully
                continue
    else:
        # Unsupported type for extra_vars; raise a descriptive error
        raise TypeError(
            "extra_vars must be a dict, string, list, tuple, or set"
        )

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: subprocess.CompletedProcess instance of the run command
    """
    import subprocess
    import json
    import shlex

    # Build base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity flag
    if verbose is not None:
        try:
            verbose_level = int(verbose)
        except Exception:
            verbose_level = None
        if isinstance(verbose_level, int) and verbose_level > 0:
            cmd.append("-" + "v" * verbose_level)

    # Append additional ansible-playbook arguments
    if isinstance(ansible_args, dict):
        for flag, value in ansible_args.items():
            # Skip empty flag
            if not flag:
                continue
            # Normalize flag to start with a dash
            if not flag.startswith("-"):
                flag = f"-{flag}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif value is None:
                continue
            elif isinstance(value, (list, tuple, set)):
                # positional values
                cmd.append(flag)
                for v in value:
                    cmd.append(str(v))
            else:
                cmd.append(flag)
                cmd.append(str(value))

    # Append inventory from workspace if provided
    inv_path = None
    for name in ("inventory_path", "inventory"):
        if hasattr(ir_workspace, name):
            inv_path = getattr(ir_workspace, name)
            if inv_path:
                break
    if inv_path:
        # Position inventory before playbook_path for ansible-playbook
        cmd = ["-i", str(inv_path)] + cmd

    # Append extra_vars
    if isinstance(extra_vars, dict) and extra_vars:
        try:
            json_str = json.dumps(extra_vars)
            cmd.extend(["--extra-vars", json_str])
        except Exception as e:
            ir_plugin.logger.error(f"Error serializing extra_vars: {e}")
            raise ValueError("Failed to serialize extra_vars") from e

    # Determine working directory
    cwd = None
    for name in ("project_root", "root", "path"):
        if hasattr(ir_workspace, name):
            cwd = getattr(ir_workspace, name)
            if cwd:
                break

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            check=True,
            text=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=getattr(ir_workspace, "env", None) or None,
        )
    except subprocess.CalledProcessError as e:
        ir_plugin.logger.error(f"Ansible playbook failed (return code {e.returncode})")
        ir_plugin.logger.error(f"stdout: {e.stdout}")
        ir_plugin.logger.error(f"stderr: {e.stderr}")
        raise

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input types
    if not isinstance(cli_args, list):
        raise TypeError("cli_args must be a list")
    if vars_dict is None:
        vars_dict = {}

    # Build the ansible-playbook command
    cmd = ["ansible-playbook"] + cli_args
    try:
        import json
        # Convert vars_dict to a JSON string; fallback to str for un-serializable objects
        cmd += ["--extra-vars", json.dumps(vars_dict, default=str)]
    except Exception as e:
        if hasattr(ir_plugin, "log"):
            try:
                ir_plugin.log(f"Failed to serialize vars_dict: {e}")
            except Exception:
                pass
        return {"rc": -1, "stdout": "", "stderr": f"Failed to serialize vars_dict: {e}"}

    # Determine current working directory based on workspace attributes
    cwd = None
    if hasattr(ir_workspace, "root"):
        cwd = ir_workspace.root
    elif hasattr(ir_workspace, "path"):
        cwd = ir_workspace.path

    # Execute the command
    try:
        import subprocess
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=True,
        )
        return {"rc": result.returncode, "stdout": result.stdout, "stderr": result.stderr}
    except subprocess.CalledProcessError as exc:
        # Command exited with non-zero status
        return {"rc": exc.returncode, "stdout": exc.stdout, "stderr": exc.stderr}
    except Exception as exc:
        if hasattr(ir_plugin, "log"):
            try:
                ir_plugin.log(f"Error running ansible-playbook: {exc}")
            except Exception:
                pass
        return {"rc": -1, "stdout": "", "stderr": str(exc)}

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        # Retrieve type mapping for the given parser; default to empty if not defined
        type_mapping = getattr(self, "_arg_type_map", {})
        arg_types = type_mapping.get(parser_name, {})

        # Iterate over a snapshot of items so we can modify the dict safely
        for arg, val in list(values_dict.items()):
            # Skip casting if no type information or value is None
            if arg not in arg_types or val is None:
                continue

            target_type = arg_types[arg]
            try:
                if target_type is bool:
                    if isinstance(val, bool):
                        cast_value = val
                    else:
                        # Accept common truthy/falsey strings
                        if isinstance(val, str):
                            lower = val.strip().lower()
                            if lower in ("true", "1", "yes", "y"):
                                cast_value = True
                            elif lower in ("false", "0", "no", "n"):
                                cast_value = False
                            else:
                                raise ValueError
                        else:
                            cast_value = bool(val)

                elif target_type is int:
                    cast_value = int(val)

                elif target_type is float:
                    cast_value = float(val)

                elif target_type is list:
                    if isinstance(val, list):
                        cast_value = val
                    elif isinstance(val, str):
                        # Split comma‑separated strings
                        cast_value = [x.strip() for x in val.split(",") if x.strip()]
                    else:
                        cast_value = [val]

                else:
                    # Generic cast using the target type constructor
                    cast_value = target_type(val)

            except Exception as exc:
                raise ValueError(
                    f"Cannot cast argument '{arg}' with value '{val}' "
                    f"to type {target_type.__name__}"
                ) from exc

            # Update the dictionary in place
            values_dict[arg] = cast_value

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Boolean conversion mapping
    bool_true_set = {'true', 'yes', '1'}
    bool_false_set = {'false', 'no', '0'}

    for key, value in list(values_dict.items()):
        # Skip non-string values
        if not isinstance(value, str):
            continue

        lowered = value.lower()
        # Handle booleans
        if lowered in bool_true_set:
            values_dict[key] = True
            continue
        if lowered in bool_false_set:
            values_dict[key] = False
            continue

        # Attempt integer conversion
        try:
            int_val = int(value)
            values_dict[key] = int_val
            continue
        except ValueError:
            pass

        # Attempt float conversion (only if not already parsed as int)
        try:
            float_val = float(value)
            values_dict[key] = float_val
            continue
        except ValueError:
            pass

        # If value is empty string or whitespace, leave as None
        if not value.strip():
            values_dict[key] = None

    # No explicit return needed; values_dict is modified in place.

