        ----------
        parser_name : str
            Name of the command parser (e.g. 'main', 'virsh', 'ospd').
        values_dict : dict
            Dictionary of argument names to string values.

        Returns
        -------
        dict
            The same dictionary instance, modified in-place.

        Raises
        ------
        TypeError
            If `values_dict` is not a dictionary.
        """
        if not isinstance(values_dict, dict):
            raise TypeError("values_dict must be a dictionary")

        # Mapping of parser names to specific casts for known arguments
        known_casts = {
            "main": {"verbosity": int, "debug": bool},
            "virsh": {"port": int, "timeout": int, "verify_ssl": bool},
            "ospd": {"max_clients": int, "config_file": str},
        }

        # Generic heuristics for coercing string values
        def _heuristic_cast(val):
            if not isinstance(val, str):
                return val
            val_str = val.strip()
            lower_val = val_str.lower()
            if lower_val in ("true", "false"):
                return lower_val == "true"
            try:
                return int(val_str)
            except ValueError:
                pass
            try:
                return float(val_str)
            except ValueError:
                pass
            return val_str

        casts = known_casts.get(parser_name, {})
        for key, raw_val in values_dict.items():
            try:
                if raw_val is None:
                    continue
                if key in casts:
                    # Use the known cast
                    values_dict[key] = casts[key](raw_val)
                else:
                    # Apply heuristic casting
                    values_dict[key] = _heuristic_cast(raw_val)
            except Exception as exc:
                # Preserve the original value if casting fails
                # Optionally log the error in a real implementation
                values_dict[key] = raw_val

        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """
        Casts arguments to correct types by modifying values_dict in place.
        Values are initially strings. This method attempts to convert
        strings that represent integers, floats, booleans, or comma‑separated
        lists into their corresponding Python types.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dictionary of arguments
        """
        def _convert_value(val):
            """
            Recursively convert a value to int, float, bool, or list.
            Leave it unchanged if conversion is not possible.
            """
            if isinstance(val, list):
                # Convert elements of the list
                return [_convert_value(v) for v in val]
            if not isinstance(val, str):
                return val
            s = val.strip()
            # Boolean conversion
            lower = s.lower()
            if lower in {"true", "false", "1", "0"}:
                return lower in {"true", "1"}
            if s == "":
                return ""
            # Integer conversion
            try:
                return int(s)
            except ValueError:
                pass
            # Float conversion
            try:
                return float(s)
            except ValueError:
                pass
            # Comma separated list conversion
            if "," in s:
                return [_convert_value(part) for part in s.split(",")]
            # Default: keep as string
            return val

        # Convert each value in the dictionary
        for key, val in values_dict.items():
            try:
                values_dict[key] = _convert_value(val)
            except Exception:
                # In case of unexpected error, preserve original value
                values_dict[key] = val
        return

