    plugin_dir_str = os.fspath(plugin_dir)
    if not os.path.isdir(plugin_dir_str):
        raise FileNotFoundError(f"The specified plugin directory does not exist or is not a directory: {plugin_dir_str}")

    spec_file = None
    # Prefer a file named exactly 'plugin.json', case insensitive
    try:
        for filename in os.listdir(plugin_dir_str):
            if filename.lower() == 'plugin.json':
                spec_file = os.path.join(plugin_dir_str, filename)
                break
    except OSError as exc:
        raise RuntimeError(f"Failed to list contents of plugin directory '{plugin_dir_str}': {exc}") from exc

    if spec_file is None:
        raise FileNotFoundError(f"No plugin.json file found in the plugin directory: {plugin_dir_str}")

    # Load the JSON spec file
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec_data = json.load(f)
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError(f"Could not read or parse plugin spec at '{spec_file}': {exc}") from exc

    # Function to flatten nested dictionaries
    def _flatten_dict(d, parent_key='', sep='.'):
        items = {}
        for key, value in d.items():
            new_key = f"{parent_key}{sep}{key}" if parent_key else key
            if isinstance(value, dict):
                items.update(_flatten_dict(value, new_key, sep=sep))
            else:
                items[new_key] = value
        return items

    if not isinstance(spec_data, dict):
