def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec.

    The function looks for a plugin specification file in the given
    directory (either ``plugin.json``, ``plugin.yaml``, ``plugin.yml`` or
    ``spec.json``/``spec.yaml``).  If the file is found, it is parsed and
    all nested dictionaries are flattened using dotted keys.  Missing or
    unreadable files result in an empty dictionary.

    :param plugin_dir: A path to the plugin's directory
    :return: A flattened dictionary containing the plugin's properties
    :raises ValueError: If ``plugin_dir`` is not a valid directory
    """
    import os
    import json

    # Helper for YAML support; import lazily
    try:
        import yaml  # type: ignore
        _YAML_AVAILABLE = True
    except Exception:
        yaml = None
        _YAML_AVAILABLE = False

    # ---- Validate input ----------------------------------------------------
    if not isinstance(plugin_dir, str):
        raise ValueError("plugin_dir must be a string")
    if not os.path.isdir(plugin_dir):
        raise ValueError(f"Not a directory: {plugin_dir}")

    # ---- Locate spec file --------------------------------------------------
    spec_filenames = [
        "plugin.json", "spec.json",
        "plugin.yaml", "spec.yaml",
        "plugin.yml", "spec.yml"
    ]
    spec_path = None
    for fn in spec_filenames:
        full = os.path.join(plugin_dir, fn)
        if os.path.isfile(full):
            spec_path = full
            break

    if not spec_path:
        # No spec file found – return empty dict
        return {}

    # ---- Load spec ----------------------------------------------------------
    try:
        with open(spec_path, "r", encoding="utf-8") as fp:
            content = fp.read()
    except Exception:
        return {}

    data = None
    try:
        if spec_path.endswith(".json"):
            data = json.loads(content)
        else:
            # YAML
            if not _YAML_AVAILABLE:
                # Fallback to simple yaml loader if available
                if yaml is None:
                    return {}
            data = yaml.safe_load(content)
    except Exception:
        return {}

    # ---- Verify data is a dict ------------------------------------------------
    if not isinstance(data, dict):
        return {}

    # ---- Flatten dict --------------------------------------------------------
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # We flatten lists by keeping the index
                for idx, item in enumerate(v):
                    if isinstance(item, dict):
                        items.update(_flatten(item, f"{new_key}{sep}{idx}", sep=sep))
                    else:
                        items[f"{new_key}{sep}{idx}"] = item
            else:
                items[new_key] = v
        return items

    return _flatten(data)

