def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.
    """
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both 'path' and 'root' must be strings")
    if root == '':
        raise ValueError("'root' cannot be an empty string")
    if path == '':
        raise ValueError("'path' cannot be an empty string")

    # Normalise trailing separators (both slash and backslash)
    def _strip_trailing_sep(p):
        while len(p) > 1 and (p.endswith('/') or p.endswith('\\')):
            p = p[:-1]
        return p

    norm_root = _strip_trailing_sep(root)
    norm_path = path  # keep the original path as we need to return the remainder

    # If the path is exactly the root, return an empty string
    if norm_path == norm_root:
        return ''

    # Attempt to strip using both common path separators
    for sep in ('/', '\\'):
        pref = norm_root + sep
        if norm_path.startswith(pref):
            return norm_path[len(pref):]

    # If no match, raise an error
    raise ValueError(f"Path '{path}' does not start with root '{root}'")

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if path is None or root is None:
        raise TypeError("path and root must not be None")
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    # Normalize the paths
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    # Empty path or root is not allowed
    if norm_path == "" or norm_root == "":
        raise ValueError("path and root must not be empty after normalization")
    try:
        common = os.path.commonpath([norm_path, norm_root])
    except Exception as exc:
        # os.path.commonpath may raise ValueError on mismatched drives etc.
        raise ValueError(f"Unable to compute common path: {exc}") from exc
    if common != norm_root:
        raise ValueError(f"root '{root}' is not a prefix of path '{path}'")
    if norm_path == norm_root:
        return ""
    # Remove the root from the path
    # Handle the case where norm_root is the filesystem root (e.g., "/")
    if norm_root == os.sep:
        remainder = norm_path.lstrip(os.sep)
    else:
        remainder = norm_path[len(norm_root):]
        if remainder.startswith(os.sep):
            remainder = remainder[len(os.sep):]
    return remainder

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate inputs
    if path is None or root is None:
        raise TypeError("Both 'path' and 'root' must be provided and must be strings")
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("'path' and 'root' must be strings")

    # Remove trailing path separators from root for consistency
    while root and root[-1] in ('/', '\\'):
        root = root[:-1]

    # If root is empty after stripping, cannot strip anything
    if root == "":
        raise ValueError("Root cannot be an empty string after normalisation")

    # Ensure path starts with root
    if not path.startswith(root):
        raise ValueError(f"Root '{root}' does not match the start of path '{path}'")

    # Get the remaining part of the path after the root
    rest = path[len(root):]

    # If the remaining part starts with a path separator, strip it
    if rest.startswith('/') or rest.startswith('\\'):
        rest = rest[1:]

    # If the rest is empty and the original path exactly matched the root, return an empty string
    return rest
